    outer_digest_block[2] = inner_state[2];
    outer_digest_block[3] = inner_state[3];
    outer_digest_block[4] = inner_state[4];
    outer_digest_block[5] = inner_state[5];
    outer_digest_block[6] = inner_state[6];
    outer_digest_block[7] = inner_state[7];
