fn typed_result_artifacts(
    module: &ForgeModuleSpec,
    outputs: &[MonsterOutputArtifact],
) -> Vec<MonsterTypedResultArtifact> {
    module
        .outputs
        .iter()
        .zip(outputs.iter())
        .map(|(spec, output)| {
            let page_bytes = artifact_page_bytes(&spec.ty);
            let byte_width = forge_type_gpu_buffer_bytes(&spec.ty).max(1);
            let page_count = byte_width
                .saturating_add(page_bytes.saturating_sub(1))
                / page_bytes.max(1);
            let element_type = forge_type_element_label(&spec.ty).to_string();
            let shape = forge_type_shape(&spec.ty);
            let layout = artifact_layout_for_type(&spec.ty, output.handoff.as_str());
            let artifact_page_hash = typed_artifact_page_hash(
                &module.name,
                &output.name,
                &output.output_hash,
                &spec.ty,
                layout,
                page_bytes,
                page_count.max(1),
            );
            MonsterTypedResultArtifact {
                schema: "forge.monster.typed_result_artifact.v1",
                name: output.name.clone(),
                forge_type: spec.ty.to_string(),
                handoff: output.handoff.clone(),
                element_type,
                shape,
                layout,
                page_bytes,
                page_count: page_count.max(1),
                native_ready: output.native_ready,
                output_hash: output.output_hash.clone(),
                artifact_page_hash,
            }
        })
        .collect()
}

fn numeric_policy_for_module(
    module: &ForgeModuleSpec,
    compute_ir_hash: &str,
) -> MonsterNumericPolicy {
    let precision = match module.cost.precision {
        ForgePrecision::F32 => "f32",
        ForgePrecision::F64 => "f64",
    };
    let float_mode = match module.cost.precision {
        ForgePrecision::F32 => "webgpu_f32_required_cpu_f64_reference",
        ForgePrecision::F64 => "cpu_f64_canonical_gpu_f32_diff_only",
    };
    let reduction_mode = if module
        .lower_to_compute_ir()
        .map(|ir| {
            ir.nodes.iter().any(|node| {
                primitive_op_name(&node.op)
                    .map(|op| matches!(op.as_str(), "reduce" | "fold" | "sum" | "mean"))
                    .unwrap_or(false)
            })
        })
        .unwrap_or(false)
    {
        "deterministic_pairwise_with_atomic_probe_hash"
    } else {
        "single_lane_or_elementwise_no_reorder"
    };
    let nan_inf_policy = if module
        .constraints
        .iter()
        .any(|constraint| constraint.canonical_source().contains("finite"))
    {
        "trap_and_deny_on_non_finite"
    } else {
        "inject_finite_guard_and_mark_suspect"
    };
    let bounds_policy = if module
        .inputs
        .iter()
        .all(|input| input.min.is_finite() && input.max.is_finite() && input.min <= input.max)
    {
        "trap_on_declared_bounds_violation"
    } else {
        "require_repair_for_unbounded_input"
    };
    let overflow_policy = "checked_integer_saturating_gpu_probe_wrapping_for_hash_only";
    let rng_policy = "counter_based_stream_seeded_by_source_contract_sample";
    let rng_stream_hash = sha256_hex(
        format!(
            "forge.monster.rng_stream.v1|{}|{}|{}|{}",
            module.name,
            module.version,
            compute_ir_hash,
            module.samples.len()
        )
        .as_bytes(),
    );
    let policy_hash = sha256_hex(
        format!(
            "forge.monster.numeric_policy.v1|{precision}|{float_mode}|{reduction_mode}|{nan_inf_policy}|{bounds_policy}|{overflow_policy}|{rng_policy}|{rng_stream_hash}"
        )
        .as_bytes(),
    );
    MonsterNumericPolicy {
        schema: "forge.monster.numeric_policy.v1",
        precision,
        float_mode,
        reduction_mode,
        nan_inf_policy,
        bounds_policy,
        overflow_policy,
        rng_policy,
        rng_stream_hash,
        policy_hash,
    }
}

fn differential_test_plan_for_module(
    module: &ForgeModuleSpec,
    compute_ir_hash: &str,
) -> MonsterDifferentialTestPlan {
    let reference_backends = match module.cost.precision {
        ForgePrecision::F32 => vec!["cpu_f64_reference_archive", "gpu_f32_candidate", "sample_assertions"],
        ForgePrecision::F64 => vec!["cpu_f64_reference_archive", "gpu_f64_candidate", "sample_assertions"],
    };
    let production_backends = vec![
        "cpu_prod_statistics_welford_quantile",
        "cpu_prod_optimization_line_search_adam",
        "cpu_prod_autodiff_dual_jvp_vjp",
        "cpu_prod_solver_rk4_stencil",
        "cpu_prod_signal_stockham_fft_convolution",
        "cpu_prod_sparse_graph_csr_graphblas",
        "cpu_prod_geometry_sdf_exact",
        "cpu_prod_physics_integrator_stencil",
        "cpu_prod_dom_ram_columnar_graph",
        "cpu_prod_crypto_hash_blocks",
    ];
    let oracle_count = module.samples.len().max(1) as u32;
    let tolerance_ppm = match module.cost.precision {
        ForgePrecision::F32 => 1_000,
        ForgePrecision::F64 => 10,
    };
    let promotion_policy = "promote_cpu_production_first_then_gpu_if_typed_buffers_within_family_tolerance";
    let metamorphic_cases = vec![
        "replay_same_seed_same_hash",
        "bounds_guard_rejects_out_of_range",
        "nan_inf_guard_rejects_non_finite",
    ];
    let plan_hash = sha256_hex(
        format!(
            "forge.monster.differential_test_plan.v2|{}|{}|{}|{}|{}|{}|{}",
            module.name,
            compute_ir_hash,
            production_backends.join(","),
            oracle_count,
            tolerance_ppm,
            promotion_policy,
            metamorphic_cases.join(",")
        )
        .as_bytes(),
    );
    MonsterDifferentialTestPlan {
        schema: "forge.monster.differential_test_plan.v2",
        reference_backends,
        production_backends,
        oracle_count,
        tolerance_ppm,
        promotion_policy,
        metamorphic_cases,
        plan_hash,
    }
}

/// Build the `/newcompute_` property plan from the Forge module's declared
/// metamorphic / property relations. Monster only classifies and hashes what
/// the LLM wrote; it never invents or evaluates the relations itself.
fn property_check_plan_for_module(module: &ForgeModuleSpec) -> MonsterPropertyCheckPlan {
    let mut relations = Vec::with_capacity(module.properties.len());
    let mut static_count = 0u32;
    let mut runtime_count = 0u32;
    for property in &module.properties {
        let enforcement = if property.kind.is_static() {
            static_count += 1;
            "static_bounds"
        } else {
            runtime_count += 1;
            "runtime_metamorphic"
        };
        let numeric_args = property
            .numeric_args
            .iter()
            .map(|value| value.to_string())
            .collect::<Vec<_>>();
        let tolerance = property.tolerance.to_string();
        let relation_hash = sha256_hex(
            format!(
                "forge.monster.property_relation.v1|{}|{}|{}|{}|{}|{}|{}",
                property.name,
                property.kind.name(),
                property.target,
                property.params.join(","),
                numeric_args.join(","),
                tolerance,
                enforcement,
            )
            .as_bytes(),
        );
        relations.push(MonsterPropertyRelation {
            schema: "forge.monster.property_relation.v1",
            name: property.name.clone(),
            kind: property.kind.name().to_string(),
            target: property.target.clone(),
            params: property.params.clone(),
            numeric_args,
            tolerance,
            enforcement,
            relation_hash,
        });
    }
    let relation_count = relations.len() as u32;
    let mut plan_text = format!(
        "forge.monster.property_check_plan.v1|{}|{}|{}|{}",
        module.name, relation_count, static_count, runtime_count
    );
    for relation in &relations {
        plan_text.push('|');
        plan_text.push_str(&relation.relation_hash);
    }
    let plan_hash = sha256_hex(plan_text.as_bytes());
    MonsterPropertyCheckPlan {
        schema: "forge.monster.property_check_plan.v1",
        relation_count,
        static_count,
        runtime_count,
        relations,
        plan_hash,
    }
}

fn forge_type_element_label(ty: &ForgeType) -> &'static str {
    match ty {
        ForgeType::Scalar(scalar)
        | ForgeType::Vec { elem: scalar, .. }
        | ForgeType::Mat { elem: scalar, .. }
        | ForgeType::Complex { elem: scalar }
        | ForgeType::Interval { elem: scalar }
        | ForgeType::Uncertainty { elem: scalar }
        | ForgeType::Array { elem: scalar, .. }
        | ForgeType::Tensor { elem: scalar, .. }
        | ForgeType::Column { elem: scalar }
        | ForgeType::Field { elem: scalar, .. }
        | ForgeType::SparseField { elem: scalar, .. } => scalar.name(),
        ForgeType::Table { .. } => "row",
        ForgeType::Graph { .. } => "edge",
        ForgeType::Snapshot | ForgeType::MemoryMap => "page",
        ForgeType::HeapObject | ForgeType::DomNode | ForgeType::DomEdge => "record",
        ForgeType::Taint { .. } => "taint",
        ForgeType::Sdf | ForgeType::NeuralSdf => "sdf_sample",
        ForgeType::VoxelPage => "voxel",
        ForgeType::Surfel => "surfel",
        ForgeType::Micromesh | ForgeType::MeshletCluster | ForgeType::GeometryPage | ForgeType::LodNode => "meshlet",
        ForgeType::MaterialGraph => "material",
        ForgeType::RadianceProbe | ForgeType::RadianceCache => "radiance",
        ForgeType::ShadowPage => "shadow",
        ForgeType::PcgGraph => "pcg",
        ForgeType::SpatialCell => "spatial_cell",
        ForgeType::LightBudget => "light",
        ForgeType::Tick | ForgeType::Bar | ForgeType::Quote | ForgeType::Trade => "market_event",
        ForgeType::Orderbook => "orderbook_level",
        ForgeType::Position | ForgeType::Pnl => "portfolio_record",
        ForgeType::Dna | ForgeType::Rna => "nucleotide",
        ForgeType::Protein => "amino_acid",
        ForgeType::Gene | ForgeType::Variant | ForgeType::Feature | ForgeType::Alignment => "bio_record",
        ForgeType::Atom => "atom",
        ForgeType::Bond => "bond",
        ForgeType::MoleculeGraph | ForgeType::Reaction | ForgeType::Conformer => "chem_record",
        ForgeType::Bitvec { .. } => "bit",
        ForgeType::PrimeField { .. } => "field_element",
        ForgeType::Curve => "curve_point",
        ForgeType::Hash => "hash_digest",
        ForgeType::Merkle => "merkle_node",
        ForgeType::Signature => "signature",
        ForgeType::Ast => "ast_node",
        ForgeType::Symbol => "symbol",
        ForgeType::Cfg => "cfg_edge",
        ForgeType::Callgraph => "call_edge",
        ForgeType::Diff => "diff_hunk",
        ForgeType::Patch => "patch_hunk",
        ForgeType::Testcase => "testcase_record",
    }
}

fn forge_type_shape(ty: &ForgeType) -> Vec<u64> {
    match ty {
        ForgeType::Scalar(_) => vec![1],
        ForgeType::Vec { lanes, .. } => vec![u64::from((*lanes).max(1))],
        ForgeType::Mat { cols, rows, .. } => vec![u64::from(*rows), u64::from(*cols)],
        ForgeType::Complex { .. } => vec![2],
        ForgeType::Interval { .. } => vec![2],
        ForgeType::Uncertainty { .. } => vec![5],
        ForgeType::Array { len, .. } => vec![u64::from(*len)],
        ForgeType::Tensor { shape, .. } => shape.iter().copied().map(u64::from).collect(),
        ForgeType::Column { .. } => vec![1024],
        ForgeType::Table { columns } => vec![1024, columns.len().max(1) as u64],
        ForgeType::Graph { .. } => vec![1024, 2],
        ForgeType::Field { rank, .. } => vec![u64::from((*rank).max(1)), 32, 32, 32],
        ForgeType::SparseField { rank, .. } => vec![u64::from((*rank).max(1)), 256, 4],
        ForgeType::Snapshot => vec![1, 64],
        ForgeType::MemoryMap => vec![1024, 4],
        ForgeType::HeapObject | ForgeType::DomNode => vec![1, 4],
        ForgeType::DomEdge => vec![1, 2],
        ForgeType::Taint { .. } => vec![1],
        ForgeType::Sdf => vec![8, 8, 8],
        ForgeType::NeuralSdf => vec![32, 16],
        ForgeType::VoxelPage => vec![16, 16, 16],
        ForgeType::Surfel => vec![1, 16],
        ForgeType::Micromesh => vec![128, 3],
        ForgeType::MaterialGraph => vec![16, 8],
        ForgeType::MeshletCluster => vec![64, 12],
        ForgeType::GeometryPage => vec![128, 16],
        ForgeType::LodNode => vec![1, 8],
        ForgeType::RadianceProbe => vec![1, 16],
        ForgeType::RadianceCache => vec![32, 16],
        ForgeType::ShadowPage => vec![128, 8],
        ForgeType::PcgGraph => vec![64, 4],
        ForgeType::SpatialCell => vec![1, 8],
        ForgeType::LightBudget => vec![64, 4],
        ForgeType::Tick | ForgeType::Quote => vec![1, 8],
        ForgeType::Trade | ForgeType::Bar => vec![1, 12],
        ForgeType::Orderbook => vec![64, 8],
        ForgeType::Position | ForgeType::Pnl => vec![1, 16],
        ForgeType::Dna | ForgeType::Rna | ForgeType::Protein => vec![4096],
        ForgeType::Gene | ForgeType::Variant | ForgeType::Feature | ForgeType::Alignment => vec![64, 8],
        ForgeType::Atom | ForgeType::Bond => vec![1, 8],
        ForgeType::MoleculeGraph => vec![256, 8],
        ForgeType::Reaction => vec![64, 12],
        ForgeType::Conformer => vec![128, 8],
        ForgeType::Bitvec { len } => vec![u64::from(*len)],
        ForgeType::PrimeField { .. } => vec![1, 8],
        ForgeType::Curve => vec![1, 12],
        ForgeType::Hash => vec![32],
        ForgeType::Merkle => vec![2, 32],
        ForgeType::Signature => vec![64],
        ForgeType::Ast => vec![256, 4],
        ForgeType::Symbol => vec![64, 4],
        ForgeType::Cfg | ForgeType::Callgraph => vec![256, 2],
        ForgeType::Diff | ForgeType::Patch => vec![128, 8],
        ForgeType::Testcase => vec![64, 8],
    }
}

fn artifact_layout_for_type(ty: &ForgeType, handoff: &str) -> &'static str {
    match (handoff, ty) {
        ("sdf", _) | ("field", ForgeType::Field { .. }) => "paged_zyx_field_bricks",
        ("field", ForgeType::SparseField { layout, .. }) => match layout {
            crate::kasm::ForgeSparseLayout::SparseGrid => "sparse_grid_coordinate_value_pages",
            crate::kasm::ForgeSparseLayout::PageTable => "sparse_field_page_table_coord_value_pages",
            crate::kasm::ForgeSparseLayout::HashGrid => "sparse_hash_grid_coord_value_pages",
        },
        (_, ForgeType::Micromesh | ForgeType::MeshletCluster | ForgeType::GeometryPage | ForgeType::LodNode) => {
            "banger_virtual_geometry_meshlet_cluster_pages"
        }
        (_, ForgeType::Tick | ForgeType::Quote | ForgeType::Trade | ForgeType::Bar) => {
            "point_in_time_market_event_pages"
        }
        (_, ForgeType::Orderbook) => "depth_ladder_orderbook_pages",
        (_, ForgeType::Position | ForgeType::Pnl) => "portfolio_pnl_ledger_pages",
        (_, ForgeType::Dna | ForgeType::Rna | ForgeType::Protein) => "packed_bio_sequence_pages",
        (_, ForgeType::Gene | ForgeType::Variant | ForgeType::Feature | ForgeType::Alignment) => {
            "bio_annotation_alignment_pages"
        }
        (_, ForgeType::Atom | ForgeType::Bond | ForgeType::MoleculeGraph) => "chem_graph_csr_pages",
        (_, ForgeType::Reaction) => "chem_reaction_transform_pages",
        (_, ForgeType::Conformer) => "chem_conformer_coordinate_pages",
        (_, ForgeType::Bitvec { .. } | ForgeType::PrimeField { .. } | ForgeType::Curve) => {
            "crypto_constant_time_scalar_object_pages"
        }
        (_, ForgeType::Hash | ForgeType::Merkle | ForgeType::Signature) => {
            "crypto_hash_merkle_signature_pages"
        }
        (_, ForgeType::Ast | ForgeType::Symbol | ForgeType::Cfg | ForgeType::Callgraph) => {
            "code_agent_typed_graph_pages"
        }
        (_, ForgeType::Diff | ForgeType::Patch | ForgeType::Testcase) => "code_agent_patch_testcase_pages",
        ("mesh_params", _) => "meshlet_parameter_pages",
        ("graph", _) | (_, ForgeType::Graph { .. }) => "csr_graph_pages",
        ("table", _) | (_, ForgeType::Table { .. }) => "columnar_table_pages",
        ("timeseries", _) => "time_major_column_pages",
        (_, ForgeType::Tensor { .. }) => "row_major_tensor_pages",
        (_, ForgeType::Interval { .. }) => "interval_lo_hi_pair",
        (_, ForgeType::Uncertainty { .. }) => "uncertainty_quantile_tuple_lo_p5_p50_p95_hi",
        (_, ForgeType::Snapshot) => "cdp_domsnapshot_capture_page",
        (_, ForgeType::MemoryMap) => "columnar_ram_memory_map_pages",
        (_, ForgeType::HeapObject) => "heap_object_record",
        (_, ForgeType::DomNode) => "dom_node_record",
        (_, ForgeType::DomEdge) => "dom_edge_record",
        (_, ForgeType::Taint { .. }) => "taint_label_record",
        (_, ForgeType::Sdf | ForgeType::NeuralSdf) => "nanovdb_like_sparse_sdf_bricks",
        (_, ForgeType::VoxelPage) => "nanovdb_like_voxel_residency_pages",
        (_, ForgeType::Surfel | ForgeType::RadianceProbe | ForgeType::RadianceCache) => {
            "banger_surfel_radiance_cache_pages"
        }
        (_, ForgeType::MaterialGraph) => "banger_physical_material_payload_pages",
        (_, ForgeType::ShadowPage) => "virtual_shadow_map_pages",
        (_, ForgeType::PcgGraph) => "hashed_pcg_graph_pages",
        (_, ForgeType::SpatialCell) => "banger_spatial_streaming_cell_pages",
        (_, ForgeType::LightBudget) => "banger_light_budget_proof_pages",
        (_, ForgeType::Array { .. } | ForgeType::Column { .. }) => "contiguous_vector_pages",
        _ => "scalar_or_packed_value",
    }
}

fn artifact_page_bytes(ty: &ForgeType) -> u64 {
    match ty {
        ForgeType::Field { .. } | ForgeType::SparseField { .. } => 64 * 1024,
        ForgeType::Graph { .. }
        | ForgeType::Table { .. }
        | ForgeType::Tensor { .. }
        | ForgeType::Snapshot
        | ForgeType::MemoryMap
        | ForgeType::Sdf
        | ForgeType::NeuralSdf
        | ForgeType::VoxelPage
        | ForgeType::Micromesh
        | ForgeType::MeshletCluster
        | ForgeType::GeometryPage
        | ForgeType::RadianceCache
        | ForgeType::ShadowPage
        | ForgeType::PcgGraph
        | ForgeType::Orderbook
        | ForgeType::Dna
        | ForgeType::Rna
        | ForgeType::Protein
        | ForgeType::MoleculeGraph
        | ForgeType::Reaction
        | ForgeType::Conformer
        | ForgeType::Ast
        | ForgeType::Cfg
        | ForgeType::Callgraph => 16 * 1024,
        _ => 4 * 1024,
    }
}

fn typed_artifact_page_hash(
    module_name: &str,
    output_name: &str,
    output_hash: &str,
    ty: &ForgeType,
    layout: &str,
    page_bytes: u64,
    page_count: u64,
) -> String {
    sha256_hex(
        format!(
            "forge.monster.typed_result_artifact.page.v1|{module_name}|{output_name}|{output_hash}|{ty}|{layout}|{page_bytes}|{page_count}"
        )
        .as_bytes(),
    )
}

fn output_kind_is_native_ready(kind: ForgeOutputKind) -> bool {
    matches!(
        kind,
        ForgeOutputKind::Vector
            | ForgeOutputKind::Field
            | ForgeOutputKind::Sdf
            | ForgeOutputKind::MeshParams
            | ForgeOutputKind::Table
            | ForgeOutputKind::Graph
            | ForgeOutputKind::Timeseries
            | ForgeOutputKind::Artifact
    )
}

fn classify_engine_lane(plan: &MonsterComputeGraphPlan) -> MonsterEngineLane {
    if plan.outputs.iter().any(|output| {
        matches!(output.handoff.as_str(), "sdf" | "mesh_params" | "field")
    }) {
        return MonsterEngineLane::NativeTandemRender;
    }
    if plan.outputs.iter().any(|output| {
        matches!(
            output.handoff.as_str(),
            "table" | "graph" | "timeseries" | "artifact"
        ) && text_mentions_dom_ram(&format!(
            "{} {} {} {}",
            plan.module_name, output.name, output.ty, output.handoff
        ))
    }) {
        return MonsterEngineLane::NativeTandemDomRam;
    }
    MonsterEngineLane::MassMath
}

fn text_mentions_dom_ram(text: &str) -> bool {
    let lower = text.to_ascii_lowercase();
    [
        "dom",
        "ram",
        "memory",
        "heap",
        "browser",
        "web",
        "node_map",
        "layout_tree",
    ]
    .iter()
    .any(|needle| lower.contains(needle))
}

fn legacy_feature_disposition() -> Vec<MonsterFeatureDisposition> {
    vec![
        MonsterFeatureDisposition {
            family: "cache/dispatch/hotplan/mmap/gpunode/atlas",
            decision: "keep_core",
            reason: "directly serves cache-miss math, native artifact planning and backend routing",
        },
        MonsterFeatureDisposition {
            family: "allocators/rings/seqlock/snapshot",
            decision: "keep_internal",
            reason: "runtime plumbing only; callers should use MonsterEngineRoute instead of tier APIs",
        },
        MonsterFeatureDisposition {
            family: "swarm/walkforward/nnue/seminaive/lua_table",
            decision: "quarantine_or_extract",
            reason: "domain helpers are not core Monster unless reattached to a verified compute graph",
        },
    ]
}

fn prepared_manifest_hash(
    route: &MonsterEngineRoute,
    cache_miss_work: &[MonsterComputeWorkUnit],
    gpu_batch_plan: &MonsterGpuBatchPlan,
    native_ready_outputs: &[MonsterOutputArtifact],
    native_tandem_artifacts: &[MonsterNativeTandemArtifact],
) -> String {
    let mut h = Sha256::new();
    h.update(b"forge.monster.prepared_compute.v1\0");
    h.update(route.schema.as_bytes());
    h.update(route.lane.label().as_bytes());
    h.update(route.native_domain.label().as_bytes());
    h.update(route.blocking_policy.as_bytes());
    h.update(route.execution_policy.as_bytes());
    h.update(route.plan.proof_hash.as_bytes());
    h.update(route.plan.fragment_hash.as_bytes());
    h.update(gpu_batch_plan.plan_hash.as_bytes());
    h.update(gpu_batch_plan.kernel_plan_hash.as_bytes());
    h.update(gpu_batch_plan.abi_hash.as_bytes());
    h.update(gpu_batch_plan.multi_adapter_schedule.schedule_hash.as_bytes());
    h.update(&[gpu_batch_plan.required as u8]);
    h.update(gpu_batch_plan.lanes.to_le_bytes());
    for work in cache_miss_work {
        h.update(work.role.as_bytes());
        h.update(b"\0");
        h.update(work.name.as_bytes());
        h.update(b"\0");
        h.update(work.fragment_hash.as_bytes());
        h.update(b"\0");
        h.update(work.backend_hint.label().as_bytes());
        h.update(b"\0");
    }
    for output in native_ready_outputs {
        h.update(output.name.as_bytes());
        h.update(b"\0");
        h.update(output.handoff.as_bytes());
        h.update(b"\0");
        h.update(output.output_hash.as_bytes());
        h.update(b"\0");
    }
    for artifact in native_tandem_artifacts {
        h.update(artifact.domain.as_bytes());
        h.update(b"\0");
        h.update(artifact.kind.as_bytes());
        h.update(b"\0");
        h.update(artifact.name.as_bytes());
        h.update(b"\0");
        h.update(artifact.artifact_hash.as_bytes());
        h.update(artifact.renderer_cache_class.as_bytes());
        h.update(artifact.renderer_residency_policy.as_bytes());
        h.update(artifact.renderer_culling_policy.as_bytes());
        h.update(artifact.renderer_cache_hash.as_bytes());
        h.update(artifact.renderer_variant_hash.as_bytes());
        h.update(artifact.renderer_promotion_hash.as_bytes());
        h.update(artifact.live_capture_policy.as_bytes());
        h.update(artifact.live_resume_cursor.as_bytes());
        h.update(artifact.live_backpressure_policy.as_bytes());
        h.update(artifact.live_section_owner.as_bytes());
        h.update(artifact.live_slice_hash.as_bytes());
        h.update(artifact.page_count.to_le_bytes());
        for page in &artifact.pages {
            h.update(page.page_hash.as_bytes());
            h.update(page.index.to_le_bytes());
        }
    }
    hex(&h.finalize())
}

fn native_tandem_artifacts_for_route(
    route: &MonsterEngineRoute,
    native_ready_outputs: &[MonsterOutputArtifact],
) -> Vec<MonsterNativeTandemArtifact> {
    let mut out = Vec::new();
    match route.lane {
        MonsterEngineLane::NativeTandemRender => {
            for output in native_ready_outputs {
                if !matches!(output.handoff.as_str(), "sdf" | "field" | "mesh_params" | "artifact") {
                    continue;
                }
                for kind in [
                    "sdf_brick",
                    "voxel_page",
                    "meshlet_page",
                    "surfel_radiance_cache",
                    "material_payload",
                ] {
                    out.push(native_render_artifact_for_output(route, output, kind));
                }
            }
        }
        MonsterEngineLane::NativeTandemDomRam => {
            for output in native_ready_outputs {
                if !matches!(output.handoff.as_str(), "graph" | "table" | "timeseries" | "artifact") {
                    continue;
                }
                for kind in [
                    "dom_graph_page",
                    "ram_region_table",
                    "browser_event_loop_slice",
                ] {
                    out.push(native_dom_ram_artifact_for_output(route, output, kind));
                }
            }
        }
        MonsterEngineLane::MassMath => {}
    }
    out
}

fn native_dom_ram_artifact_for_output(
    route: &MonsterEngineRoute,
    output: &MonsterOutputArtifact,
    kind: &'static str,
) -> MonsterNativeTandemArtifact {
    let bytes = native_dom_ram_artifact_bytes(route, output, kind);
    let layout = native_dom_ram_artifact_layout(kind);
    let page_size = native_dom_ram_artifact_page_size(kind);
    let mut pages = Vec::new();
    for (index, chunk) in bytes.chunks(page_size).enumerate() {
        let byte_offset = (index as u64).saturating_mul(page_size as u64);
        let page_hash = native_dom_ram_artifact_page_hash(route, output, kind, index as u64, byte_offset, chunk);
        pages.push(MonsterNativeTandemArtifactPage {
            schema: "forge.monster.native_tandem.artifact_page.v1",
            index: index as u64,
            byte_offset,
            bytes: chunk.to_vec(),
            page_hash,
        });
    }
    let artifact_hash = native_dom_ram_artifact_hash(route, output, kind, layout, &pages);
    MonsterNativeTandemArtifact {
        schema: "forge.monster.native_tandem.artifact.v1",
        domain: "dom_ram",
        kind,
        name: format!("{}.{}", output.name, kind),
        layout,
        renderer_cache_class: "not_renderer_cache",
        renderer_residency_policy: "not_applicable",
        renderer_culling_policy: "not_applicable",
        renderer_cache_hash: native_non_render_cache_hash(route, output, kind, layout),
        renderer_variant_hash: native_non_render_cache_hash(route, output, kind, "variant:none"),
        renderer_promotion_hash: native_non_render_cache_hash(route, output, kind, "promotion:none"),
        live_capture_policy: native_dom_ram_live_capture_policy(kind),
        live_resume_cursor: native_dom_ram_resume_cursor(route, output, kind, &pages),
        live_backpressure_policy: native_dom_ram_backpressure_policy(kind),
        live_section_owner: native_dom_ram_section_owner(kind),
        live_slice_hash: native_dom_ram_live_slice_hash(route, output, kind, layout, &pages),
        source_output_hash: output.output_hash.clone(),
        byte_len: bytes.len() as u64,
        page_count: pages.len() as u64,
        artifact_hash,
        pages,
    }
}

fn native_render_artifact_for_output(
    route: &MonsterEngineRoute,
    output: &MonsterOutputArtifact,
    kind: &'static str,
) -> MonsterNativeTandemArtifact {
    let bytes = native_render_artifact_bytes(route, output, kind);
    let layout = native_render_artifact_layout(kind);
    let page_size = native_render_artifact_page_size(kind);
    let mut pages = Vec::new();
    for (index, chunk) in bytes.chunks(page_size).enumerate() {
        let byte_offset = (index as u64).saturating_mul(page_size as u64);
        let page_hash = native_render_artifact_page_hash(route, output, kind, index as u64, byte_offset, chunk);
        pages.push(MonsterNativeTandemArtifactPage {
            schema: "forge.monster.native_tandem.artifact_page.v1",
            index: index as u64,
            byte_offset,
            bytes: chunk.to_vec(),
            page_hash,
        });
    }
    let artifact_hash = native_render_artifact_hash(route, output, kind, layout, &pages);
    let renderer_cache_class = native_render_cache_class(kind);
    let renderer_residency_policy = native_render_residency_policy(kind);
    let renderer_culling_policy = native_render_culling_policy(kind);
    let renderer_cache_hash = native_render_cache_hash(route, output, kind, layout, renderer_cache_class, &pages);
    let renderer_variant_hash = native_render_variant_hash(route, output, kind, layout, &bytes);
    let renderer_promotion_hash = native_render_promotion_hash(
        route,
        output,
        kind,
        layout,
        renderer_cache_class,
        renderer_residency_policy,
        renderer_culling_policy,
        &renderer_cache_hash,
        &renderer_variant_hash,
        &artifact_hash,
    );
    MonsterNativeTandemArtifact {
        schema: "forge.monster.native_tandem.artifact.v1",
        domain: "render_3d",
        kind,
        name: format!("{}.{}", output.name, kind),
        layout,
        renderer_cache_class,
        renderer_residency_policy,
        renderer_culling_policy,
        renderer_cache_hash,
        renderer_variant_hash,
        renderer_promotion_hash,
        live_capture_policy: "not_live_browser_capture",
        live_resume_cursor: native_non_render_cache_hash(route, output, kind, "live:none"),
        live_backpressure_policy: "not_applicable",
        live_section_owner: "native_tandem_render",
        live_slice_hash: native_non_render_cache_hash(route, output, kind, "live_slice:none"),
        source_output_hash: output.output_hash.clone(),
        byte_len: bytes.len() as u64,
        page_count: pages.len() as u64,
        artifact_hash,
        pages,
    }
}

fn native_render_artifact_layout(kind: &str) -> &'static str {
    match kind {
        "sdf_brick" => "nanovdb_like_sparse_vdb_leaf_8x8x8_f32_sdf_with_tile_mask",
        "voxel_page" => "nanovdb_like_upper_internal_node_16x16x16_u8_occupancy_mask",
        "meshlet_page" => "gpu_driven_meshlet_page_64_vertices_cone_bounds_lod_error",
        "surfel_radiance_cache" => "multi_bounce_surfel_radiance_cache_32_records_sh2",
        "material_payload" => "pbr_material_variant_payload_f32_albedo_roughness_metallic_emissive",
        _ => "native_render_artifact_page",
    }
}

fn native_render_cache_class(kind: &str) -> &'static str {
    match kind {
        "sdf_brick" => "sparse_vdb_leaf_cache",
        "voxel_page" => "sparse_vdb_internal_residency_cache",
        "meshlet_page" => "gpu_driven_meshlet_culling_cache",
        "surfel_radiance_cache" => "multi_bounce_surfel_radiance_cache",
        "material_payload" => "material_variant_payload_cache",
        _ => "native_render_cache",
    }
}

fn native_render_residency_policy(kind: &str) -> &'static str {
    match kind {
        "sdf_brick" | "voxel_page" => "hash_addressed_sparse_vdb_pages_lru_resident_by_camera_brick",
        "meshlet_page" => "gpu_visible_meshlet_pages_resident_by_lod_error_and_frustum",
        "surfel_radiance_cache" => "radiance_records_resident_by_probe_cell_and_temporal_epoch",
        "material_payload" => "material_variants_resident_by_shader_hash_and_surface_set",
        _ => "hash_addressed_native_render_pages",
    }
}

fn native_render_culling_policy(kind: &str) -> &'static str {
    match kind {
        "sdf_brick" | "voxel_page" => "hierarchical_bbox_empty_tile_skip_distance_band",
        "meshlet_page" => "sphere_cone_frustum_occlusion_lod_error_culling",
        "surfel_radiance_cache" => "normal_cone_visibility_and_bounce_energy_threshold",
        "material_payload" => "variant_key_selects_pbr_payload_without_geometry_cull",
        _ => "renderer_domain_culling_policy",
    }
}

fn native_render_artifact_page_size(kind: &str) -> usize {
    match kind {
        "material_payload" => 256,
        "sdf_brick" => 2 * 1024,
        "voxel_page" => 4 * 1024,
        _ => 8 * 1024,
    }
}

fn native_render_artifact_bytes(
    route: &MonsterEngineRoute,
    output: &MonsterOutputArtifact,
    kind: &str,
) -> Vec<u8> {
    let mut bytes = native_render_cache_header_bytes(route, output, kind);
    let payload = match kind {
        "sdf_brick" => native_sdf_brick_bytes(route, output),
        "voxel_page" => native_voxel_page_bytes(route, output),
        "meshlet_page" => native_meshlet_page_bytes(route, output),
        "surfel_radiance_cache" => native_surfel_radiance_cache_bytes(route, output),
        "material_payload" => native_material_payload_bytes(route, output),
        _ => output.output_hash.as_bytes().to_vec(),
    };
    bytes.extend_from_slice(&payload);
    bytes
}

fn native_render_seed(route: &MonsterEngineRoute, output: &MonsterOutputArtifact, kind: &str) -> u64 {
    sha256_u64(
        format!(
            "forge.monster.native_render.seed.v1|{}|{}|{}|{}|{}",
            route.plan.source_hash,
            route.plan.compute_ir_hash,
            output.output_hash,
            output.name,
            kind
        )
        .as_bytes(),
    )
}

fn push_f32(out: &mut Vec<u8>, value: f32) {
    out.extend_from_slice(&value.to_le_bytes());
}

fn push_u32(out: &mut Vec<u8>, value: u32) {
    out.extend_from_slice(&value.to_le_bytes());
}

fn native_render_cache_header_bytes(
    route: &MonsterEngineRoute,
    output: &MonsterOutputArtifact,
    kind: &str,
) -> Vec<u8> {
    let seed = native_render_seed(route, output, kind);
    let class_hash = sha256_u64(native_render_cache_class(kind).as_bytes());
    let residency_hash = sha256_u64(native_render_residency_policy(kind).as_bytes());
    let culling_hash = sha256_u64(native_render_culling_policy(kind).as_bytes());
    let mut out = Vec::with_capacity(128);
    out.extend_from_slice(b"MRC3");
    push_u32(&mut out, 1);
    push_u32(&mut out, native_render_cache_kind_code(kind));
    push_u32(&mut out, native_render_cache_lod_count(kind));
    out.extend_from_slice(&class_hash.to_le_bytes());
    out.extend_from_slice(&residency_hash.to_le_bytes());
    out.extend_from_slice(&culling_hash.to_le_bytes());
    out.extend_from_slice(&seed.to_le_bytes());
    for value in native_render_cache_bounds(kind, seed) {
        push_f32(&mut out, value);
    }
    push_u32(&mut out, native_render_cache_record_count(kind));
    push_u32(&mut out, native_render_cache_page_flags(kind));
    push_u32(&mut out, 0);
    push_u32(&mut out, 0);
    out
}

fn native_render_cache_kind_code(kind: &str) -> u32 {
    match kind {
        "sdf_brick" => 0x5644424c,
        "voxel_page" => 0x56444249,
        "meshlet_page" => 0x4d53484c,
        "surfel_radiance_cache" => 0x5352464c,
        "material_payload" => 0x4d415456,
        _ => 0,
    }
}

fn native_render_cache_lod_count(kind: &str) -> u32 {
    match kind {
        "meshlet_page" => 4,
        "sdf_brick" | "voxel_page" => 3,
        "surfel_radiance_cache" => 2,
        "material_payload" => 1,
        _ => 1,
    }
}

fn native_render_cache_record_count(kind: &str) -> u32 {
    match kind {
        "sdf_brick" => 512,
        "voxel_page" => 4096,
        "meshlet_page" => 64,
        "surfel_radiance_cache" => 32,
        "material_payload" => 4,
        _ => 1,
    }
}

fn native_render_cache_page_flags(kind: &str) -> u32 {
    match kind {
        "sdf_brick" => 0b0001_0111,
        "voxel_page" => 0b0010_0111,
        "meshlet_page" => 0b0100_1011,
        "surfel_radiance_cache" => 0b1000_1101,
        "material_payload" => 0b0001_0001,
        _ => 0,
    }
}

fn native_render_cache_bounds(kind: &str, seed: u64) -> [f32; 8] {
    let jitter = ((seed & 0xff) as f32) / 2048.0;
    match kind {
        "meshlet_page" => [-0.5 - jitter, -0.5 - jitter, -0.25, 0.5 + jitter, 0.5 + jitter, 0.25, 0.02, 0.001],
        "surfel_radiance_cache" => [-0.45, -0.45, -0.45, 0.45, 0.45, 0.45, 2.0, 0.05],
        "material_payload" => [0.0, 0.0, 0.0, 1.0, 1.0, 1.0, jitter, 1.0],
        _ => [-0.5, -0.5, -0.5, 0.5, 0.5, 0.5, 3.0, jitter],
    }
}

fn native_sdf_brick_bytes(route: &MonsterEngineRoute, output: &MonsterOutputArtifact) -> Vec<u8> {
    let seed = native_render_seed(route, output, "sdf_brick") as f32;
    let jitter = ((seed as u32 & 0xff) as f32) / 4096.0;
    let mut out = Vec::with_capacity(8 * 8 * 8 * 4);
    for z in 0..8 {
        for y in 0..8 {
            for x in 0..8 {
                let fx = (x as f32 + 0.5) / 8.0 - 0.5;
                let fy = (y as f32 + 0.5) / 8.0 - 0.5;
                let fz = (z as f32 + 0.5) / 8.0 - 0.5;
                let d = (fx * fx + fy * fy + fz * fz).sqrt() - (0.32 + jitter);
                push_f32(&mut out, d);
            }
        }
    }
    out
}

fn native_voxel_page_bytes(route: &MonsterEngineRoute, output: &MonsterOutputArtifact) -> Vec<u8> {
    let seed = native_render_seed(route, output, "voxel_page");
    let radius = 0.28 + ((seed & 0x3f) as f32) / 1024.0;
    let mut out = Vec::with_capacity(16 * 16 * 16);
    for z in 0..16 {
        for y in 0..16 {
            for x in 0..16 {
                let fx = (x as f32 + 0.5) / 16.0 - 0.5;
                let fy = (y as f32 + 0.5) / 16.0 - 0.5;
                let fz = (z as f32 + 0.5) / 16.0 - 0.5;
                let occupied = (fx * fx + fy * fy + fz * fz).sqrt() <= radius;
                out.push(if occupied { 255 } else { 0 });
            }
        }
    }
    out
}

fn native_meshlet_page_bytes(route: &MonsterEngineRoute, output: &MonsterOutputArtifact) -> Vec<u8> {
    let seed = native_render_seed(route, output, "meshlet_page") as f32;
    let wobble = ((seed as u32 & 0xff) as f32) / 2048.0;
    let mut out = Vec::with_capacity(64 * 12 * 4);
    for i in 0..64 {
        let t = i as f32 / 64.0;
        let angle = t * std::f32::consts::TAU;
        let ring = 0.35 + wobble;
        let x = ring * angle.cos();
        let y = ring * angle.sin();
        let z = (t - 0.5) * 0.25;
        let nx = angle.cos();
        let ny = angle.sin();
        let nz = 0.25;
        let radius = (x * x + y * y + z * z).sqrt() + 0.015;
        let cone_cutoff = (nx * x + ny * y + nz * z).clamp(-1.0, 1.0);
        let lod_error = 1.0 / (1.0 + i as f32);
        let occlusion_rank = ((i as u32 ^ seed as u32) & 15) as f32 / 15.0;
        let first_index = (i * 3) as f32;
        let tri_count = 2.0;
        for value in [x, y, z, nx, ny, nz, radius, cone_cutoff, lod_error, occlusion_rank, first_index, tri_count] {
            push_f32(&mut out, value);
        }
    }
    out
}

fn native_surfel_radiance_cache_bytes(route: &MonsterEngineRoute, output: &MonsterOutputArtifact) -> Vec<u8> {
    let seed = native_render_seed(route, output, "surfel_radiance_cache");
    let mut out = Vec::with_capacity(32 * 15 * 4);
    for i in 0..32u64 {
        let h = sha256_u64(&seed.wrapping_add(i).to_le_bytes());
        let u = ((h & 0xffff) as f32) / 65535.0;
        let v = (((h >> 16) & 0xffff) as f32) / 65535.0;
        let theta = u * std::f32::consts::TAU;
        let z = v * 2.0 - 1.0;
        let r = (1.0 - z * z).max(0.0).sqrt();
        let px = r * theta.cos() * 0.45;
        let py = r * theta.sin() * 0.45;
        let pz = z * 0.45;
        let radiance = 0.35 + 0.65 * u;
        let bounce1 = radiance;
        let bounce2 = radiance * (0.35 + 0.2 * v);
        let bounce3 = bounce2 * 0.42;
        let sh0 = bounce1 * 0.2820948;
        let sh1 = py * bounce2 * 0.4886025;
        let sh2 = pz * bounce2 * 0.4886025;
        let sh3 = px * bounce2 * 0.4886025;
        for value in [px, py, pz, px.signum(), py.signum(), pz.signum(), bounce1, bounce2, bounce3, sh0, sh1, sh2, sh3, u, v] {
            push_f32(&mut out, value);
        }
    }
    out
}

fn native_material_payload_bytes(route: &MonsterEngineRoute, output: &MonsterOutputArtifact) -> Vec<u8> {
    let seed = native_render_seed(route, output, "material_payload");
    let r = ((seed & 0xff) as f32) / 255.0;
    let g = (((seed >> 8) & 0xff) as f32) / 255.0;
    let b = (((seed >> 16) & 0xff) as f32) / 255.0;
    let roughness = 0.35 + (((seed >> 24) & 0xff) as f32) / 512.0;
    let metallic = (((seed >> 32) & 0xff) as f32) / 1024.0;
    let emissive = (((seed >> 40) & 0xff) as f32) / 2048.0;
    let mut out = Vec::with_capacity(4 * 12 * 4);
    for variant in 0..4 {
        let vf = variant as f32;
        let variant_roughness = (roughness + vf * 0.08).min(1.0);
        let variant_metallic = (metallic + vf * 0.04).min(1.0);
        let clearcoat = vf * 0.1;
        let transmission = if variant == 3 { 0.25 } else { 0.0 };
        let variant_hash_lane = sha256_u64(format!("{seed}:{variant}:material_variant").as_bytes()) as f32;
        for value in [r, g, b, variant_roughness, variant_metallic, emissive, clearcoat, transmission, vf, 1.0, 0.0, variant_hash_lane] {
            push_f32(&mut out, value);
        }
    }
    out
}

fn native_render_artifact_page_hash(
    route: &MonsterEngineRoute,
    output: &MonsterOutputArtifact,
    kind: &str,
    index: u64,
    byte_offset: u64,
    bytes: &[u8],
) -> String {
    let mut h = Sha256::new();
    h.update(b"forge.monster.native_tandem.artifact_page.v1\0");
    h.update(route.plan.proof_hash.as_bytes());
    h.update(output.output_hash.as_bytes());
    h.update(kind.as_bytes());
    h.update(index.to_le_bytes());
    h.update(byte_offset.to_le_bytes());
    h.update(bytes);
    hex(&h.finalize())
}

fn native_render_artifact_hash(
    route: &MonsterEngineRoute,
    output: &MonsterOutputArtifact,
    kind: &str,
    layout: &str,
    pages: &[MonsterNativeTandemArtifactPage],
) -> String {
    let mut h = Sha256::new();
    h.update(b"forge.monster.native_tandem.artifact.v1\0");
    h.update(route.plan.source_hash.as_bytes());
    h.update(route.plan.compute_ir_hash.as_bytes());
    h.update(output.output_hash.as_bytes());
    h.update(kind.as_bytes());
    h.update(layout.as_bytes());
    for page in pages {
        h.update(page.page_hash.as_bytes());
        h.update(page.index.to_le_bytes());
        h.update(page.byte_offset.to_le_bytes());
    }
    hex(&h.finalize())
}

fn native_non_render_cache_hash(
    route: &MonsterEngineRoute,
    output: &MonsterOutputArtifact,
    kind: &str,
    label: &str,
) -> String {
    sha256_hex(
        format!(
            "forge.monster.native_tandem.non_render_cache.v1|{}|{}|{}|{}",
            route.plan.proof_hash, output.output_hash, kind, label
        )
        .as_bytes(),
    )
}

fn native_render_cache_hash(
    route: &MonsterEngineRoute,
    output: &MonsterOutputArtifact,
    kind: &str,
    layout: &str,
    renderer_cache_class: &str,
    pages: &[MonsterNativeTandemArtifactPage],
) -> String {
    let mut h = Sha256::new();
    h.update(b"forge.monster.native_render.production_cache.v1\0");
    h.update(route.plan.source_hash.as_bytes());
    h.update(route.plan.compute_ir_hash.as_bytes());
    h.update(output.output_hash.as_bytes());
    h.update(kind.as_bytes());
    h.update(layout.as_bytes());
    h.update(renderer_cache_class.as_bytes());
    h.update(native_render_residency_policy(kind).as_bytes());
    h.update(native_render_culling_policy(kind).as_bytes());
    for page in pages {
        h.update(page.page_hash.as_bytes());
        h.update(page.byte_offset.to_le_bytes());
    }
    hex(&h.finalize())
}

fn native_render_variant_hash(
    route: &MonsterEngineRoute,
    output: &MonsterOutputArtifact,
    kind: &str,
    layout: &str,
    bytes: &[u8],
) -> String {
    let mut h = Sha256::new();
    h.update(b"forge.monster.native_render.variant_payload.v1\0");
    h.update(route.plan.proof_hash.as_bytes());
    h.update(output.output_hash.as_bytes());
    h.update(kind.as_bytes());
    h.update(layout.as_bytes());
    if matches!(kind, "material_payload" | "surfel_radiance_cache") {
        h.update(bytes);
    } else {
        h.update(sha256_hex(bytes).as_bytes());
    }
    hex(&h.finalize())
}

fn native_render_promotion_hash(
    route: &MonsterEngineRoute,
    output: &MonsterOutputArtifact,
    kind: &str,
    layout: &str,
    renderer_cache_class: &str,
    renderer_residency_policy: &str,
    renderer_culling_policy: &str,
    renderer_cache_hash: &str,
    renderer_variant_hash: &str,
    artifact_hash: &str,
) -> String {
    sha256_hex(
        format!(
            "forge.monster.native_render.production_promotion.v1|{}|{}|{}|{}|{}|{}|{}|{}|{}|{}",
            route.plan.proof_hash,
            output.output_hash,
            kind,
            layout,
            renderer_cache_class,
            renderer_residency_policy,
            renderer_culling_policy,
            renderer_cache_hash,
            renderer_variant_hash,
            artifact_hash
        )
        .as_bytes(),
    )
}

fn native_dom_ram_artifact_layout(kind: &str) -> &'static str {
    match kind {
        "dom_graph_page" => "live_cdp_domsnapshot_csr_graph_incremental_node_edge_u64_records",
        "ram_region_table" => "live_columnar_ram_region_table_resumable_hash_offset_len_flags",
        "browser_event_loop_slice" => "live_nonblocking_browser_event_loop_slice_backpressure_manifest",
        _ => "native_dom_ram_artifact_page",
    }
}

fn native_dom_ram_artifact_page_size(kind: &str) -> usize {
    match kind {
        "browser_event_loop_slice" => 512,
        _ => 4 * 1024,
    }
}

fn native_dom_ram_artifact_bytes(
    route: &MonsterEngineRoute,
    output: &MonsterOutputArtifact,
    kind: &str,
) -> Vec<u8> {
    let mut bytes = native_dom_ram_live_header_bytes(route, output, kind);
    let payload = match kind {
        "dom_graph_page" => native_dom_graph_page_bytes(route, output),
        "ram_region_table" => native_ram_region_table_bytes(route, output),
        "browser_event_loop_slice" => native_browser_event_loop_slice_bytes(route, output),
        _ => output.output_hash.as_bytes().to_vec(),
    };
    bytes.extend_from_slice(&payload);
    bytes
}

fn native_dom_ram_seed(route: &MonsterEngineRoute, output: &MonsterOutputArtifact, kind: &str) -> u64 {
    sha256_u64(
        format!(
            "forge.monster.native_dom_ram.seed.v1|{}|{}|{}|{}|{}",
            route.plan.source_hash,
            route.plan.compute_ir_hash,
            output.output_hash,
            output.name,
            kind
        )
        .as_bytes(),
    )
}

fn native_dom_ram_live_header_bytes(
    route: &MonsterEngineRoute,
    output: &MonsterOutputArtifact,
    kind: &str,
) -> Vec<u8> {
    let seed = native_dom_ram_seed(route, output, kind);
    let mut out = Vec::with_capacity(128);
    out.extend_from_slice(b"MDR4");
    push_u32(&mut out, 1);
    push_u32(&mut out, native_dom_ram_kind_code(kind));
    out.extend_from_slice(&seed.to_le_bytes());
    out.extend_from_slice(&sha256_u64(native_dom_ram_live_capture_policy(kind).as_bytes()).to_le_bytes());
    out.extend_from_slice(&sha256_u64(native_dom_ram_backpressure_policy(kind).as_bytes()).to_le_bytes());
    out.extend_from_slice(&sha256_u64(native_dom_ram_section_owner(kind).as_bytes()).to_le_bytes());
    push_u32(&mut out, native_dom_ram_slice_budget_micros(kind));
    push_u32(&mut out, native_dom_ram_records_per_slice(kind));
    out.extend_from_slice(&sha256_u64(route.plan.proof_hash.as_bytes()).to_le_bytes());
    out.extend_from_slice(&sha256_u64(output.output_hash.as_bytes()).to_le_bytes());
    out
}

fn native_dom_ram_kind_code(kind: &str) -> u32 {
    match kind {
        "dom_graph_page" => 0x444f4d47,
        "ram_region_table" => 0x52414d54,
        "browser_event_loop_slice" => 0x45564c53,
        _ => 0,
    }
}

fn native_dom_ram_slice_budget_micros(kind: &str) -> u32 {
    match kind {
        "dom_graph_page" => 1_500,
        "ram_region_table" => 1_000,
        "browser_event_loop_slice" => 750,
        _ => 1_000,
    }
}

fn native_dom_ram_records_per_slice(kind: &str) -> u32 {
    match kind {
        "dom_graph_page" => 64,
        "ram_region_table" => 8,
        "browser_event_loop_slice" => 1,
        _ => 1,
    }
}

fn native_dom_graph_page_bytes(route: &MonsterEngineRoute, output: &MonsterOutputArtifact) -> Vec<u8> {
    let seed = native_dom_ram_seed(route, output, "dom_graph_page");
    let mut out = Vec::with_capacity(16 * 8 * 8);
    let snapshot_epoch = sha256_u64(b"cdp:DOMSnapshot.captureSnapshot");
    for i in 0..16u64 {
        let node = sha256_u64(&seed.wrapping_add(i).to_le_bytes());
        let parent = if i == 0 { 0 } else { i - 1 };
        let edge = sha256_u64(&node.to_le_bytes());
        let depth = i.min(7);
        let flags = if i % 3 == 0 { 0b0011u64 } else { 0b0001u64 };
        let resume_cursor = seed.wrapping_add(i + 1);
        let string_table_hash = sha256_u64(format!("dom:string-table:{node}:{i}").as_bytes());
        let section_owner_hash = sha256_u64(native_dom_ram_section_owner("dom_graph_page").as_bytes());
        for value in [node, parent, edge, depth, flags, resume_cursor, string_table_hash, snapshot_epoch ^ section_owner_hash] {
            out.extend_from_slice(&value.to_le_bytes());
        }
    }
    out
}

fn native_ram_region_table_bytes(route: &MonsterEngineRoute, output: &MonsterOutputArtifact) -> Vec<u8> {
    let seed = native_dom_ram_seed(route, output, "ram_region_table");
    let mut out = Vec::with_capacity(8 * 7 * 8);
    for i in 0..8u64 {
        let region_hash = sha256_u64(&seed.wrapping_add(i * 17).to_le_bytes());
        let byte_offset = i * 4096;
        let byte_len = 4096u64;
        let flags = 0b0101u64 | ((i & 1) << 4);
        let resume_cursor = seed.wrapping_add((i + 1) * 4096);
        let pressure_score = (i + 1) * 10;
        let owner_hash = sha256_u64(native_dom_ram_section_owner("ram_region_table").as_bytes());
        for value in [region_hash, byte_offset, byte_len, flags, resume_cursor, pressure_score, owner_hash] {
            out.extend_from_slice(&value.to_le_bytes());
        }
    }
    out
}

fn native_browser_event_loop_slice_bytes(route: &MonsterEngineRoute, output: &MonsterOutputArtifact) -> Vec<u8> {
    let seed = native_dom_ram_seed(route, output, "browser_event_loop_slice");
    let mut out = Vec::with_capacity(8 * 12);
    let max_slice_micros = u64::from(native_dom_ram_slice_budget_micros("browser_event_loop_slice"));
    let max_nodes_per_slice = 64u64;
    let max_regions_per_slice = 8u64;
    let continuation_token = sha256_u64(&seed.to_le_bytes());
    let scheduler_post_task_hash = sha256_u64(b"scheduler.postTask:user-visible");
    let idle_deadline_hash = sha256_u64(b"requestIdleCallback:deadline.timeRemaining");
    let long_task_guard_hash = sha256_u64(b"PerformanceLongTaskTiming:blocking-threshold");
    let owner_hash = sha256_u64(native_dom_ram_section_owner("browser_event_loop_slice").as_bytes());
    for value in [
        max_slice_micros,
        max_nodes_per_slice,
        max_regions_per_slice,
        continuation_token,
        scheduler_post_task_hash,
        idle_deadline_hash,
        long_task_guard_hash,
        owner_hash,
        0,
        0,
        0,
        0,
    ] {
        out.extend_from_slice(&value.to_le_bytes());
    }
    out
}

fn native_dom_ram_live_capture_policy(kind: &str) -> &'static str {
    match kind {
        "dom_graph_page" => "cdp_domsnapshot_incremental_csr_capture_via_idle_slices",
        "ram_region_table" => "columnar_ram_region_incremental_capture_with_resume_cursor",
        "browser_event_loop_slice" => "scheduler_posttask_or_idlecallback_budgeted_nonblocking_slice",
        _ => "native_dom_ram_live_capture",
    }
}

fn native_dom_ram_backpressure_policy(kind: &str) -> &'static str {
    match kind {
        "dom_graph_page" => "pause_capture_when_longtask_or_owner_queue_depth_exceeds_budget",
        "ram_region_table" => "halve_region_batch_when_event_loop_budget_below_threshold",
        "browser_event_loop_slice" => "yield_before_deadline_and_resume_from_cursor",
        _ => "browser_event_loop_backpressure",
    }
}

fn native_dom_ram_section_owner(kind: &str) -> &'static str {
    match kind {
        "dom_graph_page" | "ram_region_table" | "browser_event_loop_slice" => "webexplorer.dom_ram_cartography",
        _ => "webexplorer",
    }
}

fn native_dom_ram_resume_cursor(
    route: &MonsterEngineRoute,
    output: &MonsterOutputArtifact,
    kind: &str,
    pages: &[MonsterNativeTandemArtifactPage],
) -> String {
    let mut h = Sha256::new();
    h.update(b"forge.monster.native_dom_ram.resume_cursor.v1\0");
    h.update(route.plan.proof_hash.as_bytes());
    h.update(output.output_hash.as_bytes());
    h.update(kind.as_bytes());
    for page in pages {
        h.update(page.page_hash.as_bytes());
        h.update(page.index.to_le_bytes());
    }
    hex(&h.finalize())
}

fn native_dom_ram_live_slice_hash(
    route: &MonsterEngineRoute,
    output: &MonsterOutputArtifact,
    kind: &str,
    layout: &str,
    pages: &[MonsterNativeTandemArtifactPage],
) -> String {
    let mut h = Sha256::new();
    h.update(b"forge.monster.native_dom_ram.live_slice.v1\0");
    h.update(route.plan.source_hash.as_bytes());
    h.update(route.plan.compute_ir_hash.as_bytes());
    h.update(output.output_hash.as_bytes());
    h.update(kind.as_bytes());
    h.update(layout.as_bytes());
    h.update(native_dom_ram_live_capture_policy(kind).as_bytes());
    h.update(native_dom_ram_backpressure_policy(kind).as_bytes());
    h.update(native_dom_ram_section_owner(kind).as_bytes());
    for page in pages {
        h.update(page.page_hash.as_bytes());
        h.update(page.byte_offset.to_le_bytes());
    }
    hex(&h.finalize())
}

