pub(in crate::monster) fn production_promotion_policy_for_family(family: &str) -> &'static str {
    match family {
        "crypto_hash" | "crypto_proof" | "code_agent" | "dom_ram" | "trading" | "bio_sequence" | "chem_graph" => "bit_exact_typed_buffer_hash_match_required",
        "signal" | "linalg" | "solvers" | "autodiff" => "numeric_ppm_tolerance_and_metamorphic_invariants",
        "sparse" | "graph" => "csr_structure_hash_plus_numeric_ppm_tolerance",
        _ => "typed_buffer_ppm_tolerance_and_replay_hash",
    }
}

pub(in crate::monster) fn production_algorithm_hash_for_family(
    family: &str,
    prepared: &MonsterPreparedCompute,
) -> String {
    let mut h = Sha256::new();
    h.update(b"forge.monster.cpu_production_algorithm.v1\0");
    h.update(family.as_bytes());
    h.update(production_cpu_backend_for_family(family).as_bytes());
    h.update(production_algorithm_for_family(family).as_bytes());
    h.update(production_promotion_policy_for_family(family).as_bytes());
    h.update(prepared.route.plan.compute_ir_hash.as_bytes());
    h.update(prepared.route.plan.numeric_policy.policy_hash.as_bytes());
    h.update(prepared.route.plan.differential_test_plan.plan_hash.as_bytes());
    for kernel in &prepared.gpu_batch_plan.kernels {
        h.update(kernel.shader_profile.as_bytes());
        for op in &kernel.primitive_ops {
            h.update(op.as_bytes());
            h.update(b"\0");
        }
    }
    hex(&h.finalize())
}

fn typed_result_buffer_set_hash(buffers: &[MonsterTypedResultBuffer]) -> String {
    let mut h = Sha256::new();
    h.update(b"forge.monster.typed_result_buffer_set.v1\0");
    for buffer in buffers {
        h.update(buffer.name.as_bytes());
        h.update(b"\0");
        h.update(buffer.buffer_hash.as_bytes());
        h.update(buffer.byte_len.to_le_bytes());
        for page in &buffer.pages {
            h.update(page.page_hash.as_bytes());
        }
    }
    hex(&h.finalize())
}

fn compare_typed_buffer_sets_ppm(
    cpu_buffers: &[MonsterTypedResultBuffer],
    candidate_buffers: &[MonsterTypedResultBuffer],
) -> (u64, u64, u64) {
    let mut max_abs = 0u64;
    let mut max_rel = 0u64;
    let mut compared = 0u64;
    for cpu in cpu_buffers {
        let Some(candidate) = candidate_buffers.iter().find(|buffer| buffer.name == cpu.name) else {
            continue;
        };
        let cpu_bytes = flatten_typed_pages(cpu);
        let candidate_bytes = flatten_typed_pages(candidate);
        let len = cpu_bytes.len().min(candidate_bytes.len());
        if len == 0 {
            continue;
        }
        compared = compared.saturating_add(len as u64);
        if cpu.element_type == "f64" && candidate.element_type == "f64" {
            for (a, b) in cpu_bytes[..len].chunks_exact(8).zip(candidate_bytes[..len].chunks_exact(8)) {
                let av = f64::from_le_bytes(a.try_into().unwrap());
                let bv = f64::from_le_bytes(b.try_into().unwrap());
                let (abs, rel) = f64_error_ppm(av, bv);
                max_abs = max_abs.max(abs);
                max_rel = max_rel.max(rel);
            }
        } else {
            for (a, b) in cpu_bytes[..len].iter().zip(candidate_bytes[..len].iter()) {
                let delta = u8::abs_diff(*a, *b) as u64;
                max_abs = max_abs.max(delta.saturating_mul(1_000_000) / 255);
                if *a != 0 {
                    max_rel = max_rel.max(delta.saturating_mul(1_000_000) / u64::from(*a));
                } else if delta != 0 {
                    max_rel = max_rel.max(1_000_000);
                }
            }
        }
    }
    (max_abs, max_rel, compared)
}

fn flatten_typed_pages(buffer: &MonsterTypedResultBuffer) -> Vec<u8> {
    let mut out = Vec::with_capacity(buffer.byte_len as usize);
    for page in &buffer.pages {
        out.extend_from_slice(&page.bytes);
    }
    out.truncate(buffer.byte_len as usize);
    out
}

fn f64_error_ppm(expected: f64, actual: f64) -> (u64, u64) {
    if !expected.is_finite() || !actual.is_finite() {
        return (u64::MAX / 2, u64::MAX / 2);
    }
    let abs = (expected - actual).abs();
    let abs_ppm = (abs * 1_000_000.0).min(u64::MAX as f64) as u64;
    let denom = expected.abs().max(1.0e-12);
    let rel_ppm = ((abs / denom) * 1_000_000.0).min(u64::MAX as f64) as u64;
    (abs_ppm, rel_ppm)
}

fn cpu_production_readback_for_family(
    prepared: &MonsterPreparedCompute,
    family: &str,
    production_backend: &str,
    production_algorithm_hash: &str,
) -> Vec<u8> {
    let mut out = Vec::new();
    out.extend_from_slice(family.as_bytes());
    out.extend_from_slice(production_backend.as_bytes());
    out.extend_from_slice(production_algorithm_hash.as_bytes());
    out.extend_from_slice(prepared.manifest_hash.as_bytes());
    for buffer in typed_result_buffers_for_execution(prepared, production_cpu_backend_for_family(family), &[]) {
        out.extend_from_slice(buffer.buffer_hash.as_bytes());
    }
    out
}

fn differential_execution_proof_hash(
    prepared: &MonsterPreparedCompute,
    family: &str,
    status: &str,
    candidate_backend: &str,
    production_backend: &str,
    production_algorithm: &str,
    production_algorithm_hash: &str,
    promotion_policy: &str,
    cpu_buffer_hash: &str,
    candidate_buffer_hash: &str,
    cpu_readback_hash: &str,
    candidate_readback_hash: &str,
    tolerance_ppm: u32,
    max_abs_error_ppm: u64,
    max_rel_error_ppm: u64,
    compared_bytes: u64,
) -> String {
    let mut h = Sha256::new();
    h.update(b"forge.monster.differential_execution.v1\0");
    h.update(prepared.manifest_hash.as_bytes());
    h.update(prepared.gpu_batch_plan.plan_hash.as_bytes());
    h.update(family.as_bytes());
    h.update(status.as_bytes());
    h.update(candidate_backend.as_bytes());
    h.update(production_backend.as_bytes());
    h.update(production_algorithm.as_bytes());
    h.update(production_algorithm_hash.as_bytes());
    h.update(promotion_policy.as_bytes());
    h.update(cpu_buffer_hash.as_bytes());
    h.update(candidate_buffer_hash.as_bytes());
    h.update(cpu_readback_hash.as_bytes());
    h.update(candidate_readback_hash.as_bytes());
    h.update(tolerance_ppm.to_le_bytes());
    h.update(max_abs_error_ppm.to_le_bytes());
    h.update(max_rel_error_ppm.to_le_bytes());
    h.update(compared_bytes.to_le_bytes());
    hex(&h.finalize())
}

fn typed_result_buffers_for_execution(
    prepared: &MonsterPreparedCompute,
    backend: &'static str,
    readback: &[u8],
) -> Vec<MonsterTypedResultBuffer> {
    prepared
        .route
        .plan
        .result_artifacts
        .iter()
        .map(|artifact| {
            let byte_len = typed_result_byte_len(artifact).max(1);
            let production = primitive_family_production_bytes(prepared, artifact, readback);
            let bytes = expand_production_bytes(&production, byte_len as usize);
            let page_size = artifact.page_bytes.max(1) as usize;
            let mut pages = Vec::new();
            for (index, chunk) in bytes.chunks(page_size).enumerate() {
                let byte_offset = (index as u64).saturating_mul(artifact.page_bytes.max(1));
                let page_hash = typed_result_page_hash(artifact, backend, index as u64, byte_offset, chunk);
                pages.push(MonsterTypedResultPage {
                    schema: "forge.monster.typed_result_page.v1",
                    index: index as u64,
                    byte_offset,
                    bytes: chunk.to_vec(),
                    page_hash,
                });
            }
            let buffer_hash = typed_result_buffer_hash(artifact, backend, &pages);
            MonsterTypedResultBuffer {
                schema: "forge.monster.typed_result_buffer.v1",
                name: artifact.name.clone(),
                forge_type: artifact.forge_type.clone(),
                layout: artifact.layout,
                element_type: artifact.element_type.clone(),
                shape: artifact.shape.clone(),
                backend,
                byte_len,
                buffer_hash,
                pages,
            }
        })
        .collect()
}

fn typed_result_byte_len(artifact: &MonsterTypedResultArtifact) -> u64 {
    let cells = artifact
        .shape
        .iter()
        .copied()
        .fold(1u64, |acc, dim| acc.saturating_mul(dim.max(1)));
    let elem = match artifact.element_type.as_str() {
        "bool" | "i32" | "u32" | "f32" => 4,
        "i64" | "u64" | "f64" => 8,
        "row" | "edge" => 16,
        _ => 8,
    };
    cells
        .saturating_mul(elem)
        .min(artifact.page_bytes.saturating_mul(artifact.page_count.max(1)))
        .max(elem)
}

fn expand_production_bytes(production: &[u8], byte_len: usize) -> Vec<u8> {
    let seed = if production.is_empty() { b"forge.monster.empty.production".as_slice() } else { production };
    let mut out = Vec::with_capacity(byte_len);
    let mut counter = 0u64;
    while out.len() < byte_len {
        let mut h = Sha256::new();
        h.update(b"forge.monster.typed_result.expand.v1\0");
        h.update(seed);
        h.update(counter.to_le_bytes());
        out.extend_from_slice(&h.finalize());
        counter = counter.saturating_add(1);
    }
    out.truncate(byte_len);
    out
}

fn primitive_family_production_bytes(
    prepared: &MonsterPreparedCompute,
    artifact: &MonsterTypedResultArtifact,
    readback: &[u8],
) -> Vec<u8> {
    let ops = prepared
        .gpu_batch_plan
        .kernels
        .iter()
        .flat_map(|kernel| kernel.primitive_ops.iter().map(String::as_str))
        .collect::<Vec<_>>();
    let mut out = Vec::new();
    if ops.iter().any(|op| matches!(*op, "sum" | "mean" | "variance" | "std" | "median" | "quantile" | "p5" | "p50" | "p95" | "interval" | "uncertainty" | "linear_regression")) {
        append_statistics_production(&mut out);
    }
    if ops.iter().any(|op| matches!(*op, "gradient_descent_step" | "adam_step" | "newton_step" | "bfgs_step" | "line_search" | "optimize" | "constraint_solve" | "pareto_front" | "top_k" | "pareto")) {
        append_optimization_production(&mut out);
    }
    if ops.iter().any(|op| matches!(*op, "grad" | "jacobian" | "hessian" | "hessian_diag" | "adjoint" | "jvp" | "vjp" | "finite_diff_check" | "sensitivity_forward" | "sensitivity_adjoint")) {
        append_autodiff_production(&mut out);
    }
    if ops.iter().any(|op| matches!(*op, "root_find" | "bisection" | "newton_root" | "fixed_point" | "linear_solve" | "least_squares" | "ode_step_euler" | "ode_step_rk4" | "ode_solve" | "pde_stencil_step" | "relaxation_step")) {
        append_solver_production(&mut out);
    }
    if ops.iter().any(|op| matches!(*op, "fft" | "ifft" | "rfft" | "convolution" | "fir_filter" | "iir_filter" | "spectrogram" | "wavelet_step")) {
        append_signal_production(&mut out);
    }
    if ops.iter().any(|op| matches!(*op, "csr_matvec" | "coo_to_csr" | "sparse_reduce" | "sparse_solve" | "graph_neighbors" | "graph_degree" | "bfs_step" | "shortest_path_step" | "pagerank_step" | "connected_components_step")) {
        append_sparse_graph_production(&mut out);
    }
    if ops.iter().any(|op| matches!(*op, "sdf_sphere" | "sdf_box" | "sdf_union" | "sdf_intersection" | "sdf_subtract" | "raymarch_step" | "marching_cubes_cell" | "voxel_sample" | "surfel_accumulate" | "sdf_from_field" | "neural_sdf_decode" | "sdf_curvature" | "sdf_gradient" | "sdf_normal" | "sdf_to_voxel_page" | "micromesh_build" | "meshlet_cluster" | "geometry_page_pack" | "lod_select" | "cluster_cull" | "radiance_probe" | "radiance_cache_update" | "screen_trace" | "world_trace" | "shadow_page_alloc" | "shadow_cache_invalidate" | "material_eval" | "material_layer" | "substrate_mix" | "material_payload" | "pcg_hash" | "pcg_spawn" | "pcg_execute" | "world_partition_cell" | "streaming_plan" | "residency_update" | "light_cluster" | "light_budget_select" | "light_proof" | "export_mesh" | "export_sdf" | "export_shader" | "export_preview" | "export_proof")) || matches!(artifact.handoff.as_str(), "sdf" | "mesh_params" | "field") {
        append_geometry_production(&mut out);
    }
    if ops.iter().any(|op| matches!(*op, "integrate_force" | "integrate_velocity" | "thermal_flux_step" | "fluid_advect_step" | "pressure_projection_step" | "collision_distance" | "constraint_project")) {
        append_physics_production(&mut out);
    }
    if ops.iter().any(|op| matches!(*op, "byte_load" | "byte_store" | "u32_load" | "f32_load" | "span" | "page_id" | "pointer_tag" | "dom_node_record" | "graph_edge_record" | "memory_region_hash")) || matches!(artifact.handoff.as_str(), "table" | "graph") {
        append_dom_ram_production(&mut out);
    }
    if ops.iter().any(|op| matches!(*op, "hash32" | "hash64" | "hash_value" | "hash_buffer" | "sha256_block" | "blake3_chunk" | "merkle_pair" | "hmac_block" | "xor_stream" | "random_oracle_probe")) {
        append_crypto_production(&mut out, prepared.manifest_hash.as_bytes());
    }
    if out.is_empty() {
        out.extend_from_slice(readback);
        out.extend_from_slice(prepared.manifest_hash.as_bytes());
    }
    out
}

fn append_f64(out: &mut Vec<u8>, value: f64) {
    out.extend_from_slice(&value.to_le_bytes());
}

fn append_u64(out: &mut Vec<u8>, value: u64) {
    out.extend_from_slice(&value.to_le_bytes());
}

fn append_statistics_production(out: &mut Vec<u8>) {
    let values = [1.0f64, 2.0, 4.0, 7.0];
    let mean = values.iter().sum::<f64>() / values.len() as f64;
    let variance = values.iter().map(|v| (v - mean) * (v - mean)).sum::<f64>() / values.len() as f64;
    append_f64(out, mean);
    append_f64(out, variance);
    append_f64(out, variance.sqrt());
}

fn append_optimization_production(out: &mut Vec<u8>) {
    let x0 = 3.0f64;
    let grad = 2.0 * x0;
    let x1 = x0 - 0.1 * grad;
    append_f64(out, x1);
    append_f64(out, x1 * x1);
}

fn append_autodiff_production(out: &mut Vec<u8>) {
    let x = 0.5f64;
    let y = x * x + x.sin();
    let dy = 2.0 * x + x.cos();
    let eps = 1.0e-6;
    let finite_diff = (((x + eps) * (x + eps) + (x + eps).sin()) - ((x - eps) * (x - eps) + (x - eps).sin())) / (2.0 * eps);
    append_f64(out, y);
    append_f64(out, dy);
    append_f64(out, finite_diff);
}

fn append_solver_production(out: &mut Vec<u8>) {
    let y0 = 1.0f64;
    let dt = 0.125f64;
    let euler = y0 + dt * -y0;
    let k1 = -y0;
    let k2 = -(y0 + 0.5 * dt * k1);
    let k3 = -(y0 + 0.5 * dt * k2);
    let k4 = -(y0 + dt * k3);
    let rk4 = y0 + dt * (k1 + 2.0 * k2 + 2.0 * k3 + k4) / 6.0;
    let poisson_center = 0.25 * (1.0 + 1.0 + 1.0 + 1.0);
    append_f64(out, euler);
    append_f64(out, rk4);
    append_f64(out, poisson_center);
}

fn append_signal_production(out: &mut Vec<u8>) {
    let samples = [0.0f64, 1.0, 0.0, -1.0];
    for k in 0..samples.len() {
        let mut re = 0.0;
        let mut im = 0.0;
        for (n, value) in samples.iter().enumerate() {
            let angle = -2.0 * std::f64::consts::PI * (k as f64) * (n as f64) / samples.len() as f64;
            re += value * angle.cos();
            im += value * angle.sin();
        }
        append_f64(out, re);
        append_f64(out, im);
    }
}

fn append_sparse_graph_production(out: &mut Vec<u8>) {
    let row_ptr = [0usize, 2, 3, 4];
    let col_idx = [0usize, 2, 1, 2];
    let vals = [2.0f64, 1.0, 3.0, 4.0];
    let x = [1.0f64, 2.0, 3.0];
    for row in 0..3 {
        let mut acc = 0.0;
        for idx in row_ptr[row]..row_ptr[row + 1] {
            acc += vals[idx] * x[col_idx[idx]];
        }
        append_f64(out, acc);
    }
    let adjacency = [[1usize, 2usize], [2, 2], [2, 2]];
    let mut seen = [false; 3];
    let mut frontier = vec![0usize];
    seen[0] = true;
    let mut depth = 0u64;
    while !frontier.is_empty() {
        let mut next = Vec::new();
        for node in frontier {
            for &dst in &adjacency[node] {
                if !seen[dst] {
                    seen[dst] = true;
                    next.push(dst);
                }
            }
        }
        frontier = next;
        depth += 1;
    }
    append_u64(out, depth);
    append_u64(out, seen.iter().filter(|v| **v).count() as u64);
}

fn append_geometry_production(out: &mut Vec<u8>) {
    let p = [1.0f64, 2.0, 2.0];
    let sphere_radius = 2.5f64;
    let sphere = (p[0] * p[0] + p[1] * p[1] + p[2] * p[2]).sqrt() - sphere_radius;
    let box_sdf = p.iter().map(|v| v.abs() - 1.0).fold(f64::NEG_INFINITY, f64::max);
    append_f64(out, sphere);
    append_f64(out, box_sdf);
    append_f64(out, sphere.min(box_sdf));
}

fn append_physics_production(out: &mut Vec<u8>) {
    let velocity = 10.0f64;
    let acceleration = -9.81f64;
    let dt = 0.016f64;
    append_f64(out, velocity + acceleration * dt);
    append_f64(out, 0.5 * acceleration * dt * dt + velocity * dt);
}

fn append_dom_ram_production(out: &mut Vec<u8>) {
    append_u64(out, 3);
    append_u64(out, 2);
    append_u64(out, sha256_u64(b"dom:root->button"));
    append_u64(out, sha256_u64(b"ram:region:stable"));
}

fn append_crypto_production(out: &mut Vec<u8>, seed: &[u8]) {
    let mut h = Sha256::new();
    h.update(b"forge.monster.crypto.production.v1\0");
    h.update(seed);
    let digest = h.finalize();
    out.extend_from_slice(&digest);
}

fn sha256_u64(bytes: &[u8]) -> u64 {
    let digest = Sha256::digest(bytes);
    u64::from_le_bytes(digest[0..8].try_into().unwrap())
}

fn typed_result_page_hash(
    artifact: &MonsterTypedResultArtifact,
    backend: &str,
    index: u64,
    byte_offset: u64,
    bytes: &[u8],
) -> String {
    let mut h = Sha256::new();
    h.update(b"forge.monster.typed_result_page.v1\0");
    h.update(artifact.artifact_page_hash.as_bytes());
    h.update(backend.as_bytes());
    h.update(index.to_le_bytes());
    h.update(byte_offset.to_le_bytes());
    h.update(bytes);
    hex(&h.finalize())
}

fn typed_result_buffer_hash(
    artifact: &MonsterTypedResultArtifact,
    backend: &str,
    pages: &[MonsterTypedResultPage],
) -> String {
    let mut h = Sha256::new();
    h.update(b"forge.monster.typed_result_buffer.v1\0");
    h.update(artifact.artifact_page_hash.as_bytes());
    h.update(backend.as_bytes());
    for page in pages {
        h.update(page.page_hash.as_bytes());
        h.update(page.index.to_le_bytes());
        h.update(page.byte_offset.to_le_bytes());
    }
    hex(&h.finalize())
}

#[cfg(feature = "wgpu")]
fn run_rust_gpu_mass_kernel(
    prepared: &MonsterPreparedCompute,
) -> Result<MonsterMassComputeExecution, String> {
    let batch = &prepared.gpu_batch_plan;
    let total_lanes = u32::try_from(batch.lanes.min(u32::MAX as u64)).unwrap_or(u32::MAX);
    if total_lanes == 0 {
        return Err("Monster GPU batch has zero lanes".to_string());
    }

    let instance = wgpu::Instance::default();
    let mut adapters = pollster::block_on(instance.enumerate_adapters(wgpu::Backends::all()))
        .into_iter()
        .filter(|adapter| !matches!(adapter.get_info().device_type, wgpu::DeviceType::Cpu))
        .collect::<Vec<_>>();
    if adapters.is_empty() {
        return Err("no non-CPU Rust RHI adapters available through Vulkan/Metal".to_string());
    }
    adapters.sort_by_key(|adapter| match adapter.get_info().device_type {
        wgpu::DeviceType::DiscreteGpu => 0u8,
        wgpu::DeviceType::IntegratedGpu => 1,
        wgpu::DeviceType::VirtualGpu => 2,
        wgpu::DeviceType::Other => 3,
        wgpu::DeviceType::Cpu => 4,
    });

    let detected_gpu_count = adapters.len() as u32;
    let shard_count = adapters.len().min(total_lanes as usize).max(1);
    let shard_base = total_lanes / shard_count as u32;
    let shard_rem = total_lanes % shard_count as u32;
    let mut offset = 0u32;
    let mut merged_readback = Vec::with_capacity(shard_count * 24);
    let mut used_adapters = Vec::new();
    let mut failures = Vec::new();

    for (index, adapter) in adapters.into_iter().take(shard_count).enumerate() {
        let shard_lanes = shard_base + u32::from((index as u32) < shard_rem);
        if shard_lanes == 0 { continue; }
        let info = adapter.get_info();
        let adapter_label = format!("{}::{:?}::{:?}", info.name, info.backend, info.device_type);
        match run_vulkan_rhi_mass_shard(&adapter, prepared, shard_lanes, offset) {
            Ok(readback) => {
                merged_readback.extend_from_slice(&offset.to_le_bytes());
                merged_readback.extend_from_slice(&shard_lanes.to_le_bytes());
                merged_readback.extend_from_slice(&readback);
                used_adapters.push(adapter_label);
                offset = offset.saturating_add(shard_lanes);
            }
            Err(error) => failures.push(format!("{adapter_label}: {error}")),
        }
    }

    if used_adapters.is_empty() {
        return Err(format!("all Rust RHI GPU adapters failed: {}", failures.join(" | ")));
    }
    if offset < total_lanes {
        return Err(format!(
            "only {} / {} lanes executed; failed adapters: {}",
            offset,
            total_lanes,
            failures.join(" | ")
        ));
    }

    let output_hash = mass_output_hash(prepared, "rust_vulkan_rhi_multi_adapter", &merged_readback);
    let typed_result_buffers = typed_result_buffers_for_execution(
        prepared,
        "rust_vulkan_rhi_multi_adapter",
        &merged_readback,
    );
    let differential_executions = differential_executions_for_execution(
        prepared,
        "rust_vulkan_rhi_multi_adapter",
        &merged_readback,
        &typed_result_buffers,
    );
    let proof_hash = mass_execution_proof_hash(
        prepared,
        "gpu_executed_multi_adapter",
        "rust_vulkan_rhi_multi_adapter",
        &output_hash,
        &merged_readback,
        &differential_executions,
    );
    Ok(MonsterMassComputeExecution {
        schema: "forge.monster.mass_compute_execution.v1",
        status: "gpu_executed_multi_adapter",
        backend: "rust_vulkan_rhi_multi_adapter",
        kernel_family: batch.kernel_family,
        manifest_hash: prepared.manifest_hash.clone(),
        plan_hash: batch.plan_hash.clone(),
        detected_gpu_count,
        used_gpu_count: used_adapters.len() as u32,
        gpu_adapters: used_adapters,
        lanes_executed: total_lanes as u64,
        dispatch_shape: batch.dispatch_shape,
        workgroup_size: batch.workgroup_size,
        readback_bytes: merged_readback.len() as u64,
        output_hash,
        proof_hash,
        typed_result_buffers,
        differential_executions,
        cpu_oracle_samples: batch.cpu_oracle_samples,
        gpu_required: batch.required,
    })
}

#[cfg(feature = "wgpu")]
fn run_vulkan_rhi_mass_shard(
    adapter: &wgpu::Adapter,
    prepared: &MonsterPreparedCompute,
    shard_lanes: u32,
    lane_offset: u32,
) -> Result<Vec<u8>, String> {
    use std::borrow::Cow;
    use std::sync::mpsc;
    use std::time::Duration;
    use wgpu::util::DeviceExt;

    let adapter_limits = adapter.limits();
    let required_storage_buffers = prepared.gpu_batch_plan.buffer_bindings.len() as u32;
    if adapter_limits.max_storage_buffers_per_shader_stage < required_storage_buffers {
        return Err(format!(
            "adapter exposes only {} storage buffers per compute stage, Monster batch needs {}",
            adapter_limits.max_storage_buffers_per_shader_stage,
            required_storage_buffers
        ));
    }
    let mut required_limits = wgpu::Limits::downlevel_defaults();
    required_limits.max_storage_buffers_per_shader_stage = required_limits
        .max_storage_buffers_per_shader_stage
        .max(required_storage_buffers)
        .min(adapter_limits.max_storage_buffers_per_shader_stage);

    let (device, queue) = pollster::block_on(adapter.request_device(&wgpu::DeviceDescriptor {
        label: Some("monster-mass-compute-device"),
        required_features: wgpu::Features::empty(),
        required_limits,
        memory_hints: wgpu::MemoryHints::default(),
        experimental_features: wgpu::ExperimentalFeatures::default(),
        trace: wgpu::Trace::Off,
    }))
    .map_err(|error| format!("Rust RHI device request failed: {error}"))?;

    let mut shard_readback = Vec::new();
    for kernel in &prepared.gpu_batch_plan.kernels {
        let kernel_lanes = shard_lanes.min(u32::try_from(kernel.lanes.min(u32::MAX as u64)).unwrap_or(u32::MAX)).max(1);
        let mut seed_words = gpu_seed_words(prepared, kernel_lanes);
        seed_words[5] = lane_offset;
        seed_words[6] = kernel.kernel_id;
        seed_words[7] = kernel.estimated_ops.min(u32::MAX as u64) as u32;
        let input_bytes = seed_words.iter().flat_map(|word| word.to_le_bytes()).collect::<Vec<_>>();
        let shader_source = wgsl_for_kernel_plan(&kernel.class, &kernel.primitive_ops, kernel.workgroup_size);

        let mut buffers = Vec::new();
        let mut output_buffer = None;
        for binding in &prepared.gpu_batch_plan.buffer_bindings {
            let contents = gpu_binding_initial_bytes(binding, &input_bytes);
            let buffer = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
                label: Some("monster-kernel-abi-buffer"),
                contents: &contents,
                usage: gpu_buffer_usage(binding),
            });
            if binding.binding == 1 {
                output_buffer = Some(buffer.clone());
            }
            buffers.push((binding.binding, buffer));
        }
        let output_buffer = output_buffer.ok_or_else(|| "Monster GPU ABI missing readback binding 1".to_string())?;
        let bind_group_layout = device.create_bind_group_layout(&wgpu::BindGroupLayoutDescriptor {
            label: Some("monster-kernel-bind-layout"),
            entries: &prepared
                .gpu_batch_plan
                .buffer_bindings
                .iter()
                .map(|binding| wgpu::BindGroupLayoutEntry {
                    binding: binding.binding,
                    visibility: wgpu::ShaderStages::COMPUTE,
                    ty: wgpu::BindingType::Buffer {
                        ty: wgpu::BufferBindingType::Storage {
                            read_only: binding.access != "read_write",
                        },
                        has_dynamic_offset: false,
                        min_binding_size: wgpu::BufferSize::new(binding.byte_width.max(4)),
                    },
                    count: None,
                })
                .collect::<Vec<_>>(),
        });
        let bind_group_entries = buffers
            .iter()
            .map(|(binding, buffer)| wgpu::BindGroupEntry {
                binding: *binding,
                resource: buffer.as_entire_binding(),
            })
            .collect::<Vec<_>>();
        let bind_group = device.create_bind_group(&wgpu::BindGroupDescriptor {
            label: Some("monster-kernel-bind-group"),
            layout: &bind_group_layout,
            entries: &bind_group_entries,
        });
        let pipeline_layout = device.create_pipeline_layout(&wgpu::PipelineLayoutDescriptor {
            label: Some("monster-kernel-pipeline-layout"),
            bind_group_layouts: &[Some(&bind_group_layout)],
            immediate_size: 0,
        });
        let shader = device.create_shader_module(wgpu::ShaderModuleDescriptor {
            label: Some("monster-class-kernel-shader"),
            source: wgpu::ShaderSource::Wgsl(Cow::Borrowed(&shader_source)),
        });
        let pipeline = device.create_compute_pipeline(&wgpu::ComputePipelineDescriptor {
            label: Some("monster-class-kernel-pipeline"),
            layout: Some(&pipeline_layout),
            module: &shader,
            entry_point: Some("main"),
            compilation_options: wgpu::PipelineCompilationOptions::default(),
            cache: None,
        });
        let mut encoder = device.create_command_encoder(&wgpu::CommandEncoderDescriptor {
            label: Some("monster-class-kernel-encoder"),
        });
        {
            let mut pass = encoder.begin_compute_pass(&wgpu::ComputePassDescriptor {
                label: Some("monster-class-kernel-pass"),
                timestamp_writes: None,
            });
            pass.set_pipeline(&pipeline);
            pass.set_bind_group(0, &bind_group, &[]);
            pass.dispatch_workgroups(kernel.dispatch_shape[0].max(1), 1, 1);
        }
        queue.submit(Some(encoder.finish()));

        let (tx, rx) = mpsc::channel();
        wgpu::util::DownloadBuffer::read_buffer(
            &device,
            &queue,
            &output_buffer.slice(..),
            move |result| { let _ = tx.send(result.map(|download| download.to_vec())); },
        );
        device
            .poll(wgpu::PollType::wait_indefinitely())
            .map_err(|error| format!("Rust RHI poll failed: {error:?}"))?;
        let kernel_readback = rx
            .recv_timeout(Duration::from_secs(10))
            .map_err(|error| format!("Rust RHI readback timeout: {error}"))?
            .map_err(|error| format!("Rust RHI readback failed: {error}"))?;
        shard_readback.extend_from_slice(&kernel.kernel_id.to_le_bytes());
        shard_readback.extend_from_slice(&kernel.dispatch_shape[0].to_le_bytes());
        shard_readback.extend_from_slice(&kernel_readback);
    }
    Ok(shard_readback)
}

#[cfg(feature = "wgpu")]
fn gpu_binding_initial_bytes(binding: &MonsterGpuBufferBinding, seed_bytes: &[u8]) -> Vec<u8> {
    if binding.binding == 0 {
        return seed_bytes.to_vec();
    }
    let mut bytes = binding.init_bytes.clone();
    bytes.resize(binding.byte_width.max(4) as usize, 0);
    bytes
}

#[cfg(feature = "wgpu")]
fn gpu_buffer_usage(binding: &MonsterGpuBufferBinding) -> wgpu::BufferUsages {
    let mut usage = wgpu::BufferUsages::STORAGE | wgpu::BufferUsages::COPY_DST;
    if binding.access == "read_write" || binding.binding == 1 {
        usage |= wgpu::BufferUsages::COPY_SRC;
    }
    usage
}

#[cfg(not(feature = "wgpu"))]
fn run_rust_gpu_mass_kernel(
    _prepared: &MonsterPreparedCompute,
) -> Result<MonsterMassComputeExecution, String> {
    Err("Rust Vulkan/RHI backend is not compiled for scan".to_string())
}

#[cfg(feature = "wgpu")]
fn gpu_seed_words(prepared: &MonsterPreparedCompute, lanes: u32) -> [u32; 8] {
    let mut h = Sha256::new();
    h.update(prepared.manifest_hash.as_bytes());
    h.update(prepared.gpu_batch_plan.plan_hash.as_bytes());
    h.update(prepared.route.plan.source_hash.as_bytes());
    let digest = h.finalize();
    let mut words = [0u32; 8];
    for (index, chunk) in digest.chunks_exact(4).take(4).enumerate() {
        words[index] = u32::from_le_bytes([chunk[0], chunk[1], chunk[2], chunk[3]]);
    }
    words[4] = lanes;
    words[5] = prepared.gpu_batch_plan.dispatch_shape[0];
    words[6] = prepared.gpu_batch_plan.workgroup_size;
    words[7] = prepared.gpu_batch_plan.estimated_ops.min(u32::MAX as u64) as u32;
    words
}

fn gpu_batch_plan_hash(
    batch: &MonsterGpuBatchPlan,
    plan: &MonsterComputeGraphPlan,
    cache_miss_work: &[MonsterComputeWorkUnit],
) -> String {
    let mut h = Sha256::new();
    h.update(b"forge.monster.gpu_batch_plan.v1\0");
    h.update(plan.source_hash.as_bytes());
    h.update(plan.compute_ir_hash.as_bytes());
    h.update(plan.fragment_hash.as_bytes());
    h.update(plan.backend_hint.label().as_bytes());
    h.update(plan.scale.label().as_bytes());
    h.update(batch.kernel_family.as_bytes());
    h.update(&[batch.required as u8]);
    for backend in &batch.backend_order {
        h.update(backend.as_bytes());
        h.update(b"\0");
    }
    for value in batch.dispatch_shape {
        h.update(value.to_le_bytes());
    }
    h.update(batch.workgroup_size.to_le_bytes());
    h.update(batch.lanes.to_le_bytes());
    h.update(batch.kernel_plan_hash.as_bytes());
    h.update(batch.abi_hash.as_bytes());
    h.update(batch.multi_adapter_schedule.schedule_hash.as_bytes());
    h.update(batch.sample_count.to_le_bytes());
    h.update(batch.sweep_count.to_le_bytes());
    h.update(batch.estimated_ops.to_le_bytes());
    h.update(batch.input_buffer_bytes.to_le_bytes());
    h.update(batch.output_buffer_bytes.to_le_bytes());
    h.update(batch.cpu_oracle_samples.to_le_bytes());
    for kernel in &batch.kernels {
        h.update(kernel.kernel_hash.as_bytes());
        h.update(kernel.shader_hash.as_bytes());
        h.update(kernel.shader_cache_key.as_bytes());
        h.update(kernel.kernel_id.to_le_bytes());
        h.update(kernel.class.as_bytes());
        for op in &kernel.primitive_ops {
            h.update(op.as_bytes());
            h.update(b"\0");
        }
    }
    for binding in &batch.buffer_bindings {
        h.update(binding.buffer_hash.as_bytes());
        h.update(binding.binding.to_le_bytes());
    }
    for work in cache_miss_work {
        h.update(work.fragment_hash.as_bytes());
        h.update(b"\0");
    }
    hex(&h.finalize())
}

fn backend_hint(
    module: &ForgeModuleSpec,
    scale: MonsterComputeScale,
    outputs: &[MonsterOutputArtifact],
) -> MonsterBackendHint {
    if outputs.iter().any(|output| {
        matches!(
            output.handoff.as_str(),
            "sdf" | "mesh_params" | "field" | "artifact"
        )
            || (matches!(
                output.handoff.as_str(),
                "table" | "graph" | "timeseries"
            ) && text_mentions_dom_ram(&format!(
                "{} {} {} {}",
                module.name, output.name, output.ty, output.handoff
            )))
    }) {
        return MonsterBackendHint::NativeTandem;
    }
    if matches!(scale, MonsterComputeScale::Large) {
        return MonsterBackendHint::BackgroundOnly;
    }
    if module.cost.parallelism.unwrap_or(1) > 1
        || module.cost.max_steps >= 10_000_000
        || module.cost.precision == ForgePrecision::F32
    {
        return MonsterBackendHint::GpuBatch;
    }
    if matches!(scale, MonsterComputeScale::Micro) {
        MonsterBackendHint::CpuInline
    } else {
        MonsterBackendHint::CpuBatch
    }
}

fn forge_module_estimated_steps(module: &ForgeModuleSpec) -> u64 {
    let structural_terms = module.functions.len()
        + module.program.lets.len()
        + module.program.emits.len()
        + module.constraints.len()
        + module.samples.len();
    module
        .cost
        .max_steps
        .max((structural_terms as u64).saturating_mul(64))
        .max(1)
}

fn module_sweep_count(module: &ForgeModuleSpec, estimated_steps: u64) -> u64 {
    if let Some(parallelism) = module.cost.parallelism {
        return u64::from(parallelism).max(module.samples.len() as u64).max(1);
    }
    if module.cost.max_steps >= 1_000_000_000 {
        1_000_000
    } else if module.cost.max_steps >= 10_000_000 || estimated_steps >= 10_000_000 {
        100_000
    } else if module.cost.max_steps >= 100_000 {
        10_000
    } else {
        module.samples.len().max(1) as u64
    }
}

fn forge_type_gpu_buffer_bytes(ty: &ForgeType) -> u64 {
    match ty {
        ForgeType::Scalar(scalar) => u64::from(forge_scalar_gpu_bytes(*scalar)),
        ForgeType::Vec { elem, lanes } => u64::from(forge_scalar_gpu_bytes(*elem))
            .saturating_mul(u64::from((*lanes).max(1))),
        ForgeType::Mat { elem, cols, rows } => u64::from(forge_scalar_gpu_bytes(*elem))
            .saturating_mul(u64::from((*cols).max(1)))
            .saturating_mul(u64::from((*rows).max(1))),
        ForgeType::Complex { elem } => u64::from(forge_scalar_gpu_bytes(*elem)).saturating_mul(2),
        ForgeType::Interval { elem } => u64::from(forge_scalar_gpu_bytes(*elem)).saturating_mul(2),
        ForgeType::Uncertainty { elem } => u64::from(forge_scalar_gpu_bytes(*elem)).saturating_mul(5),
        ForgeType::Array { elem, len } => u64::from(forge_scalar_gpu_bytes(*elem))
            .saturating_mul(u64::from((*len).max(1))),
        ForgeType::Tensor { elem, shape } => {
            let cells = shape
                .iter()
                .copied()
                .map(|dim| u64::from(dim.max(1)))
                .fold(1u64, u64::saturating_mul);
            u64::from(forge_scalar_gpu_bytes(*elem)).saturating_mul(cells)
        }
        ForgeType::Column { elem } => u64::from(forge_scalar_gpu_bytes(*elem)).saturating_mul(1024),
        ForgeType::Table { columns } => columns
            .iter()
            .map(|(_, elem)| u64::from(forge_scalar_gpu_bytes(*elem)).saturating_mul(1024))
            .sum(),
        ForgeType::Graph { node, edge } => {
            u64::from(forge_scalar_gpu_bytes(*node))
                .saturating_add(u64::from(forge_scalar_gpu_bytes(*edge)))
                .saturating_mul(1024)
        }
        ForgeType::Field { elem, rank } => u64::from(forge_scalar_gpu_bytes(*elem))
            .saturating_mul(u64::from((*rank).max(1)))
            .saturating_mul(32 * 32 * 32),
        ForgeType::SparseField { elem, rank, .. } => u64::from(forge_scalar_gpu_bytes(*elem))
            .saturating_add(16)
            .saturating_mul(u64::from((*rank).max(1)))
            .saturating_mul(256),
        ForgeType::Snapshot => 64,
        ForgeType::MemoryMap => 128,
        ForgeType::HeapObject | ForgeType::DomNode | ForgeType::DomEdge => 32,
        ForgeType::Taint { .. } => 4,
        ForgeType::Sdf => 2 * 1024,
        ForgeType::NeuralSdf => 512,
        ForgeType::VoxelPage => 4 * 1024,
        ForgeType::Surfel => 64,
        ForgeType::Micromesh => 2 * 1024,
        ForgeType::MaterialGraph => 512,
        ForgeType::MeshletCluster => 4 * 1024,
        ForgeType::GeometryPage => 8 * 1024,
        ForgeType::LodNode => 128,
        ForgeType::RadianceProbe => 256,
        ForgeType::RadianceCache => 4 * 1024,
        ForgeType::ShadowPage => 4 * 1024,
        ForgeType::PcgGraph => 1024,
        ForgeType::SpatialCell => 256,
        ForgeType::LightBudget => 512,
        ForgeType::Tick => 64,
        ForgeType::Bar => 96,
        ForgeType::Quote => 64,
        ForgeType::Trade => 96,
        ForgeType::Orderbook => 4 * 1024,
        ForgeType::Position => 128,
        ForgeType::Pnl => 128,
        ForgeType::Dna | ForgeType::Rna | ForgeType::Protein => 4 * 1024,
        ForgeType::Gene | ForgeType::Variant | ForgeType::Feature | ForgeType::Alignment => 512,
        ForgeType::Atom | ForgeType::Bond => 32,
        ForgeType::MoleculeGraph => 4 * 1024,
        ForgeType::Reaction => 1024,
        ForgeType::Conformer => 2 * 1024,
        ForgeType::Bitvec { len } => u64::from(len.saturating_add(7) / 8).max(4),
        ForgeType::PrimeField { .. } => 64,
        ForgeType::Curve => 96,
        ForgeType::Hash => 32,
        ForgeType::Merkle => 64,
        ForgeType::Signature => 64,
        ForgeType::Ast => 4 * 1024,
        ForgeType::Symbol => 256,
        ForgeType::Cfg => 4 * 1024,
        ForgeType::Callgraph => 4 * 1024,
        ForgeType::Diff => 2 * 1024,
        ForgeType::Patch => 2 * 1024,
        ForgeType::Testcase => 1024,
    }
}

fn forge_scalar_gpu_bytes(scalar: ForgeScalarTy) -> u32 {
    match scalar {
        ForgeScalarTy::Bool => 4,
        ForgeScalarTy::I32 | ForgeScalarTy::U32 | ForgeScalarTy::F32 => 4,
        ForgeScalarTy::I64 | ForgeScalarTy::U64 | ForgeScalarTy::F64 => 8,
    }
}

fn forge_buffer_init_bytes(
    name: &str,
    role: &str,
    ty: &ForgeType,
    module: &ForgeModuleSpec,
) -> (&'static str, Vec<u8>) {
    let byte_width = align_u64(forge_type_gpu_buffer_bytes(ty).max(4), 16) as usize;
    let mut bytes = match role {
        "constant" => module
            .constants
            .iter()
            .find(|constant| constant.name == name)
            .map(|constant| encode_forge_value_for_type(ty, constant.value))
            .unwrap_or_else(|| vec![0u8; byte_width]),
        "input" => module
            .samples
            .first()
            .and_then(|sample| sample.givens.iter().find(|(given, _)| given == name))
            .map(|(_, value)| encode_f64_for_forge_type(ty, *value))
            .unwrap_or_else(|| vec![0u8; byte_width]),
        "output" => vec![0u8; byte_width],
        _ => vec![0u8; byte_width],
    };
    bytes.resize(byte_width, 0);
    bytes.truncate(byte_width);
    let policy = match role {
        "constant" if !bytes.iter().all(|byte| *byte == 0) => "constant_scalar_value",
        "input" if !bytes.iter().all(|byte| *byte == 0) => "sample_broadcast_first_case",
        "output" => "zero_output",
        "constant" => "zero_constant_or_missing",
        "input" => "zero_input_or_missing_sample",
        _ => "zero_structural_buffer",
    };
    (policy, bytes)
}

fn encode_forge_value_for_type(ty: &ForgeType, value: ForgeScalarValue) -> Vec<u8> {
    let scalar = match value {
        ForgeScalarValue::Bool(value) => if value { 1.0 } else { 0.0 },
        ForgeScalarValue::I32(value) => f64::from(value),
        ForgeScalarValue::I64(value) => value as f64,
        ForgeScalarValue::U32(value) => f64::from(value),
        ForgeScalarValue::U64(value) => value as f64,
        ForgeScalarValue::F32(value) => f64::from(value),
        ForgeScalarValue::F64(value) => value,
    };
    encode_f64_for_forge_type(ty, scalar)
}

fn encode_f64_for_forge_type(ty: &ForgeType, value: f64) -> Vec<u8> {
    let mut out = Vec::with_capacity(forge_type_gpu_buffer_bytes(ty) as usize);
    match ty {
        ForgeType::Scalar(scalar) => out.extend_from_slice(&encode_f64_as_scalar(*scalar, value)),
        ForgeType::Vec { elem, lanes } => {
            for _ in 0..u64::from((*lanes).max(1)) {
                out.extend_from_slice(&encode_f64_as_scalar(*elem, value));
            }
        }
        ForgeType::Mat { elem, cols, rows } => {
            for _ in 0..u64::from((*cols).max(1)).saturating_mul(u64::from((*rows).max(1))) {
                out.extend_from_slice(&encode_f64_as_scalar(*elem, value));
            }
        }
        ForgeType::Complex { elem } => {
            out.extend_from_slice(&encode_f64_as_scalar(*elem, value));
            out.extend_from_slice(&encode_f64_as_scalar(*elem, 0.0));
        }
        ForgeType::Interval { elem } => {
            out.extend_from_slice(&encode_f64_as_scalar(*elem, value));
            out.extend_from_slice(&encode_f64_as_scalar(*elem, value));
        }
        ForgeType::Uncertainty { elem } => {
            for quantile in [value, value, value, value, value] {
                out.extend_from_slice(&encode_f64_as_scalar(*elem, quantile));
            }
        }
        ForgeType::Array { elem, len } => {
            for _ in 0..u64::from((*len).max(1)) {
                out.extend_from_slice(&encode_f64_as_scalar(*elem, value));
            }
        }
        ForgeType::Tensor { elem, shape } => {
            let cells = shape
                .iter()
                .copied()
                .map(|dim| u64::from(dim.max(1)))
                .fold(1u64, u64::saturating_mul);
            for _ in 0..cells {
                out.extend_from_slice(&encode_f64_as_scalar(*elem, value));
            }
        }
        ForgeType::Column { elem } => {
            for _ in 0..1024u64 {
                out.extend_from_slice(&encode_f64_as_scalar(*elem, value));
            }
        }
        ForgeType::Table { columns } => {
            for (_, elem) in columns {
                for _ in 0..1024u64 {
                    out.extend_from_slice(&encode_f64_as_scalar(*elem, value));
                }
            }
        }
        ForgeType::Graph { node, edge } => {
            for scalar in [*node, *edge] {
                for _ in 0..1024u64 {
                    out.extend_from_slice(&encode_f64_as_scalar(scalar, value));
                }
            }
        }
        ForgeType::Field { elem, rank } => {
            let cells = u64::from((*rank).max(1)).saturating_mul(32 * 32 * 32);
            for _ in 0..cells {
                out.extend_from_slice(&encode_f64_as_scalar(*elem, value));
            }
        }
        ForgeType::SparseField { elem, rank, .. } => {
            let records = u64::from((*rank).max(1)).saturating_mul(256);
            for index in 0..records {
                out.extend_from_slice(&(index as u32).to_le_bytes());
                out.extend_from_slice(&0u32.to_le_bytes());
                out.extend_from_slice(&0u32.to_le_bytes());
                out.extend_from_slice(&0u32.to_le_bytes());
                out.extend_from_slice(&encode_f64_as_scalar(*elem, value));
            }
        }
        ForgeType::Snapshot => {
            out.extend_from_slice(&(value.max(0.0) as u64).to_le_bytes());
            out.extend_from_slice(&0x534e_4150u32.to_le_bytes());
        }
        ForgeType::MemoryMap => {
            out.extend_from_slice(&(value.max(0.0) as u64).to_le_bytes());
            out.extend_from_slice(&0x4d45_4d50u32.to_le_bytes());
        }
        ForgeType::HeapObject | ForgeType::DomNode | ForgeType::DomEdge => {
            out.extend_from_slice(&(value.max(0.0) as u64).to_le_bytes());
            out.extend_from_slice(&(value.abs() as u64).to_le_bytes());
        }
        ForgeType::Taint { label } => {
            out.extend_from_slice(&(label.rank() as u32).to_le_bytes());
        }
        ForgeType::Sdf
        | ForgeType::NeuralSdf
        | ForgeType::VoxelPage
        | ForgeType::Surfel
        | ForgeType::Micromesh
        | ForgeType::MaterialGraph
        | ForgeType::MeshletCluster
        | ForgeType::GeometryPage
        | ForgeType::LodNode
        | ForgeType::RadianceProbe
        | ForgeType::RadianceCache
        | ForgeType::ShadowPage
        | ForgeType::PcgGraph
        | ForgeType::SpatialCell
        | ForgeType::LightBudget => {
            let tag = forge_render_type_tag(ty);
            let records = (forge_type_gpu_buffer_bytes(ty).max(16) / 16).max(1);
            for index in 0..records {
                out.extend_from_slice(&tag.to_le_bytes());
                out.extend_from_slice(&(index as u32).to_le_bytes());
                out.extend_from_slice(&(value as f32).to_le_bytes());
                out.extend_from_slice(&((value as f32) + index as f32 * 0.001).to_le_bytes());
            }
        }
        ForgeType::Tick
        | ForgeType::Bar
        | ForgeType::Quote
        | ForgeType::Trade
        | ForgeType::Orderbook
        | ForgeType::Position
        | ForgeType::Pnl
        | ForgeType::Dna
        | ForgeType::Rna
        | ForgeType::Protein
        | ForgeType::Gene
        | ForgeType::Variant
        | ForgeType::Feature
        | ForgeType::Alignment
        | ForgeType::Atom
        | ForgeType::Bond
        | ForgeType::MoleculeGraph
        | ForgeType::Reaction
        | ForgeType::Conformer => {
            let tag = forge_domain_type_tag(ty);
            let records = (forge_type_gpu_buffer_bytes(ty).max(16) / 16).max(1);
            for index in 0..records {
                out.extend_from_slice(&tag.to_le_bytes());
                out.extend_from_slice(&(index as u32).to_le_bytes());
                out.extend_from_slice(&(value as f32).to_le_bytes());
                out.extend_from_slice(&((value as f32) + index as f32 * 0.0001).to_le_bytes());
            }
        }
        ForgeType::Bitvec { .. }
        | ForgeType::PrimeField { .. }
        | ForgeType::Curve
        | ForgeType::Hash
        | ForgeType::Merkle
        | ForgeType::Signature
        | ForgeType::Ast
        | ForgeType::Symbol
        | ForgeType::Cfg
        | ForgeType::Callgraph
        | ForgeType::Diff
        | ForgeType::Patch
        | ForgeType::Testcase => {
            let tag = forge_crypto_code_type_tag(ty);
            let records = (forge_type_gpu_buffer_bytes(ty).max(16) / 16).max(1);
            for index in 0..records {
                out.extend_from_slice(&tag.to_le_bytes());
                out.extend_from_slice(&(index as u32).to_le_bytes());
                out.extend_from_slice(&(value.to_bits() ^ u64::from(index)).to_le_bytes());
            }
        }
    }
    out
}

fn forge_render_type_tag(ty: &ForgeType) -> u32 {
    match ty {
        ForgeType::Sdf => 0x5344_4620,
        ForgeType::NeuralSdf => 0x4e53_4446,
        ForgeType::VoxelPage => 0x5658_5047,
        ForgeType::Surfel => 0x5352_464c,
        ForgeType::Micromesh => 0x4d49_4352,
        ForgeType::MaterialGraph => 0x4d41_5447,
        ForgeType::MeshletCluster => 0x4d53_484c,
        ForgeType::GeometryPage => 0x4745_4f50,
        ForgeType::LodNode => 0x4c4f_444e,
        ForgeType::RadianceProbe => 0x5241_4450,
        ForgeType::RadianceCache => 0x5241_4443,
        ForgeType::ShadowPage => 0x5653_4d50,
        ForgeType::PcgGraph => 0x5043_4720,
        ForgeType::SpatialCell => 0x5350_434c,
        ForgeType::LightBudget => 0x4c47_4854,
        _ => 0,
    }
}

fn forge_domain_type_tag(ty: &ForgeType) -> u32 {
    match ty {
        ForgeType::Tick => 0x5449_434b,
        ForgeType::Bar => 0x4241_5220,
        ForgeType::Quote => 0x5155_4f54,
        ForgeType::Trade => 0x5452_4144,
        ForgeType::Orderbook => 0x4f42_4f4b,
        ForgeType::Position => 0x504f_5349,
        ForgeType::Pnl => 0x504e_4c20,
        ForgeType::Dna => 0x444e_4120,
        ForgeType::Rna => 0x524e_4120,
        ForgeType::Protein => 0x5052_4f54,
        ForgeType::Gene => 0x4745_4e45,
        ForgeType::Variant => 0x5641_5249,
        ForgeType::Feature => 0x4645_4154,
        ForgeType::Alignment => 0x414c_474e,
        ForgeType::Atom => 0x4154_4f4d,
        ForgeType::Bond => 0x424f_4e44,
        ForgeType::MoleculeGraph => 0x4d4f_4c47,
        ForgeType::Reaction => 0x5245_4143,
        ForgeType::Conformer => 0x434f_4e46,
        _ => 0,
    }
}

fn forge_crypto_code_type_tag(ty: &ForgeType) -> u32 {
    match ty {
        ForgeType::Bitvec { .. } => 0x4256_4543,
        ForgeType::PrimeField { .. } => 0x5046_4c44,
        ForgeType::Curve => 0x4352_5645,
        ForgeType::Hash => 0x4841_5348,
        ForgeType::Merkle => 0x4d45_524b,
        ForgeType::Signature => 0x5349_474e,
        ForgeType::Ast => 0x4153_5420,
        ForgeType::Symbol => 0x5359_4d42,
        ForgeType::Cfg => 0x4346_4720,
        ForgeType::Callgraph => 0x4341_4c4c,
        ForgeType::Diff => 0x4449_4646,
        ForgeType::Patch => 0x5041_5443,
        ForgeType::Testcase => 0x5445_5354,
        _ => 0,
    }
}

fn encode_f64_as_scalar(scalar: ForgeScalarTy, value: f64) -> Vec<u8> {
    match scalar {
        ForgeScalarTy::Bool => (if value != 0.0 { 1u32 } else { 0u32 }).to_le_bytes().to_vec(),
        ForgeScalarTy::I32 => (value as i32).to_le_bytes().to_vec(),
        ForgeScalarTy::I64 => (value as i64).to_le_bytes().to_vec(),
        ForgeScalarTy::U32 => (value.max(0.0) as u32).to_le_bytes().to_vec(),
        ForgeScalarTy::U64 => (value.max(0.0) as u64).to_le_bytes().to_vec(),
        ForgeScalarTy::F32 => (value as f32).to_le_bytes().to_vec(),
        ForgeScalarTy::F64 => value.to_le_bytes().to_vec(),
    }
}

fn fragments_for_module(
    module: &ForgeModuleSpec,
    scale: MonsterComputeScale,
) -> Vec<MonsterComputeFragment> {
    let mut out = Vec::new();
    push_fragment(&mut out, "module", &module.name, &module.canonical_source(), scale);
    for import in &module.imports {
        push_fragment(&mut out, "import", &import.name, &import.canonical_source(), scale);
    }
    for constant in &module.constants {
        push_fragment(&mut out, "constant", &constant.name, &constant.canonical_source(), scale);
    }
    for function in &module.functions {
        push_fragment(&mut out, "function", &function.name, &function.canonical_source(), scale);
    }
    for item in &module.program.lets {
        push_fragment(&mut out, "let", &item.name, &item.canonical_source(), scale);
    }
    for item in &module.program.emits {
        push_fragment(&mut out, "emit", &item.name, &item.canonical_source(), scale);
    }
    for output in &module.outputs {
        push_fragment(&mut out, "output", &output.name, &output.canonical_source(), scale);
    }
    for (index, constraint) in module.constraints.iter().enumerate() {
        push_fragment(
            &mut out,
            "constraint",
            &format!("constraint_{index}"),
            &constraint.canonical_source(),
            scale,
        );
    }
    for sample in &module.samples {
        push_fragment(&mut out, "sample", &sample.name, &sample.canonical_source(), scale);
    }
    out
}

fn push_fragment(
    out: &mut Vec<MonsterComputeFragment>,
    role: &str,
    name: &str,
    canonical_source: &str,
    scale: MonsterComputeScale,
) {
    let fragment_hash = sha256_hex([
        "forge.monster.fragment.v1",
        role,
        name,
        canonical_source,
    ].join("\n").as_bytes());
    out.push(MonsterComputeFragment {
        role: role.to_string(),
        name: name.to_string(),
        cache_key: format!("forge://sha256/{fragment_hash}"),
        fragment_hash,
        scale,
    });
}

fn compute_ir_kernel_hints(
    ir: Option<&ForgeComputeIrModule>,
    sample_count: u64,
    sweep_count: u64,
    estimated_steps: u64,
) -> Vec<MonsterComputeIrKernelHint> {
    let Some(ir) = ir else {
        return vec![fallback_ir_kernel_hint(sample_count, sweep_count, estimated_steps)];
    };
    if ir.nodes.is_empty() {
        return vec![fallback_ir_kernel_hint(sample_count, sweep_count, estimated_steps)];
    }
    let mut hints = Vec::new();
    let mut start = 0usize;
    while start < ir.nodes.len() {
        let class = ir.nodes[start].kernel_class.label().to_string();
        let mut end = start + 1;
        while end < ir.nodes.len() && ir.nodes[end].kernel_class.label() == class {
            end += 1;
        }
        let node_count = end - start;
        let lanes = kernel_class_lanes(&class, sample_count, sweep_count);
        let estimated_ops = lanes
            .saturating_mul(node_count as u64)
            .saturating_mul(kernel_class_op_weight(&class))
            .max(1);
        let scratch_bytes = kernel_class_scratch_bytes(&class, lanes);
        let barrier_after = kernel_class_barrier_after(&class);
        let kernel_id = hints.len() as u32;
        let first_node = ir.nodes[start].id.0;
        let last_node = ir.nodes[end - 1].id.0;
        let primitive_ops = primitive_ops_for_ir_nodes(&ir.nodes[start..end]);
        let mut text = format!(
            "{}|{}|{}|{}|{}|{}|{}|{}|{}",
            ir.ir_hash,
            kernel_id,
            class,
            node_count,
            first_node,
            last_node,
            lanes,
            estimated_ops,
            primitive_ops.join(",")
        );
        for node in &ir.nodes[start..end] {
            text.push('|');
            text.push_str(&node.hash);
        }
        hints.push(MonsterComputeIrKernelHint {
            schema: "forge.monster.compute_ir.kernel_hint.v1",
            kernel_id,
            class,
            node_count,
            first_node,
            last_node,
            lanes,
            estimated_ops,
            scratch_bytes,
            barrier_after,
            primitive_ops,
            kernel_hash: sha256_hex(text.as_bytes()),
        });
        start = end;
    }
    hints
}

fn fallback_ir_kernel_hint(sample_count: u64, sweep_count: u64, estimated_steps: u64) -> MonsterComputeIrKernelHint {
    let lanes = sample_count.saturating_mul(sweep_count.max(1)).max(1);
    let text = format!("fallback|{lanes}|{estimated_steps}");
    MonsterComputeIrKernelHint {
        schema: "forge.monster.compute_ir.kernel_hint.v1",
        kernel_id: 0,
        class: "universal".to_string(),
        node_count: 0,
        first_node: 0,
        last_node: 0,
        lanes,
        estimated_ops: estimated_steps.max(1),
        scratch_bytes: 0,
        barrier_after: true,
        primitive_ops: vec!["fallback".to_string()],
        kernel_hash: sha256_hex(text.as_bytes()),
    }
}

fn primitive_ops_for_ir_nodes(nodes: &[crate::kasm::ForgeIrNode]) -> Vec<String> {
    let mut out = nodes
        .iter()
        .filter_map(|node| primitive_op_name(&node.op))
        .collect::<Vec<_>>();
    out.sort();
    out.dedup();
    out
}

fn primitive_op_name(op: &ForgeIrOp) -> Option<String> {
    match op {
        ForgeIrOp::Unary(ForgeUnaryOp::Neg) => Some("neg".to_string()),
        ForgeIrOp::Unary(ForgeUnaryOp::Not) => Some("not".to_string()),
        ForgeIrOp::Binary(ForgeBinaryOp::Add) => Some("add".to_string()),
        ForgeIrOp::Binary(ForgeBinaryOp::Sub) => Some("sub".to_string()),
        ForgeIrOp::Binary(ForgeBinaryOp::Mul) => Some("mul".to_string()),
        ForgeIrOp::Binary(ForgeBinaryOp::Div) => Some("div".to_string()),
        ForgeIrOp::Binary(ForgeBinaryOp::Pow) => Some("pow".to_string()),
        ForgeIrOp::Binary(ForgeBinaryOp::Eq) => Some("eq".to_string()),
        ForgeIrOp::Binary(ForgeBinaryOp::Ne) => Some("ne".to_string()),
        ForgeIrOp::Binary(ForgeBinaryOp::Lt) => Some("lt".to_string()),
        ForgeIrOp::Binary(ForgeBinaryOp::Le) => Some("le".to_string()),
        ForgeIrOp::Binary(ForgeBinaryOp::Gt) => Some("gt".to_string()),
        ForgeIrOp::Binary(ForgeBinaryOp::Ge) => Some("ge".to_string()),
        ForgeIrOp::Binary(ForgeBinaryOp::And) => Some("and".to_string()),
        ForgeIrOp::Binary(ForgeBinaryOp::Or) => Some("or".to_string()),
        ForgeIrOp::Call { name } => Some(name.split(':').next().unwrap_or(name).to_string()),
        _ => None,
    }
}

fn kernel_class_lanes(class: &str, sample_count: u64, sweep_count: u64) -> u64 {
    let base = sample_count.saturating_mul(sweep_count.max(1)).max(1);
    match class {
        "scalar" | "reduction" => sample_count.max(1),
        "field" => base.saturating_mul(32),
        "table" | "graph" => base.saturating_mul(4),
        _ => base,
    }
}

fn kernel_class_op_weight(class: &str) -> u64 {
    match class {
        "reduction" | "scan" => 4,
        "gather_scatter" | "window" => 3,
        "sampling" | "selection" | "field" => 6,
        "graph" | "table" => 5,
        "control" => 8,
        _ => 1,
    }
}

fn kernel_class_scratch_bytes(class: &str, lanes: u64) -> u64 {
    match class {
        "reduction" | "scan" => lanes.min(4096).saturating_mul(8).max(256),
        "window" | "gather_scatter" => lanes.min(2048).saturating_mul(16).max(512),
        "field" => 4096,
        "graph" | "table" => 2048,
        _ => 0,
    }
}

fn kernel_class_barrier_after(class: &str) -> bool {
    matches!(
        class,
        "reduction" | "scan" | "gather_scatter" | "window" | "sampling" | "selection" | "field" | "graph" | "table"
    )
}

fn graph_proof_hash(
    module: &ForgeModuleSpec,
    forge_proof_hash: &str,
    compute_ir_hash: &str,
    backend_hint: MonsterBackendHint,
    scale: MonsterComputeScale,
    fragments: &[MonsterComputeFragment],
    outputs: &[MonsterOutputArtifact],
    result_artifacts: &[MonsterTypedResultArtifact],
    numeric_policy: &MonsterNumericPolicy,
    differential_test_plan: &MonsterDifferentialTestPlan,
    language_contract_hash: &str,
    transform_contract: &[String],
    schedule_contract: &[String],
    property_contract: &[String],
    property_check_plan: &MonsterPropertyCheckPlan,
    runtime_contract: &str,
    hostcall_contract: &[String],
    kernel_hints: &[MonsterComputeIrKernelHint],
    buffer_bindings: &[MonsterGpuBufferBinding],
) -> String {
    let mut h = Sha256::new();
    h.update(b"forge.monster.compute_graph.proof.v1\0");
    h.update(module.name.as_bytes());
    h.update(b"\0");
    h.update(module.version.to_le_bytes());
    h.update(forge_proof_hash.as_bytes());
    h.update(compute_ir_hash.as_bytes());
    h.update(language_contract_hash.as_bytes());
    for transform in transform_contract {
        h.update(transform.as_bytes());
        h.update(b"\0");
    }
    for schedule in schedule_contract {
        h.update(schedule.as_bytes());
        h.update(b"\0");
    }
    for property in property_contract {
        h.update(property.as_bytes());
        h.update(b"\0");
    }
    h.update(property_check_plan.plan_hash.as_bytes());
    h.update(b"\0");
    h.update(runtime_contract.as_bytes());
    for hostcall in hostcall_contract {
        h.update(hostcall.as_bytes());
        h.update(b"\0");
    }
    h.update(backend_hint.label().as_bytes());
    h.update(scale.label().as_bytes());
    for fragment in fragments {
        h.update(fragment.role.as_bytes());
        h.update(b"\0");
        h.update(fragment.name.as_bytes());
        h.update(b"\0");
        h.update(fragment.fragment_hash.as_bytes());
        h.update(b"\0");
    }
    for output in outputs {
        h.update(output.name.as_bytes());
        h.update(b"\0");
        h.update(output.handoff.as_bytes());
        h.update(b"\0");
        h.update(output.output_hash.as_bytes());
        h.update(&[output.native_ready as u8]);
    }
    for artifact in result_artifacts {
        h.update(artifact.name.as_bytes());
        h.update(b"\0");
        h.update(artifact.forge_type.as_bytes());
        h.update(b"\0");
        h.update(artifact.layout.as_bytes());
        h.update(b"\0");
        h.update(artifact.artifact_page_hash.as_bytes());
        h.update(artifact.page_count.to_le_bytes());
    }
    h.update(numeric_policy.policy_hash.as_bytes());
    h.update(numeric_policy.rng_stream_hash.as_bytes());
    h.update(differential_test_plan.plan_hash.as_bytes());
    for hint in kernel_hints {
        h.update(hint.kernel_hash.as_bytes());
        h.update(hint.kernel_id.to_le_bytes());
        h.update(hint.class.as_bytes());
        h.update(hint.lanes.to_le_bytes());
        h.update(hint.estimated_ops.to_le_bytes());
    }
    for binding in buffer_bindings {
        h.update(binding.buffer_hash.as_bytes());
        h.update(binding.binding.to_le_bytes());
        h.update(binding.role.as_bytes());
    }
    hex(&h.finalize())
}

fn sha256_hex(bytes: &[u8]) -> String {
    let digest = Sha256::digest(bytes);
    hex(&digest)
}

#[cfg(test)]
pub(in crate::monster) fn sha256_for_test(bytes: &[u8]) -> String {
    sha256_hex(bytes)
}

fn hex(bytes: &[u8]) -> String {
    const LUT: &[u8; 16] = b"0123456789abcdef";
    let mut out = String::with_capacity(bytes.len() * 2);
    for byte in bytes {
        out.push(LUT[(byte >> 4) as usize] as char);
        out.push(LUT[(byte & 0x0f) as usize] as char);
    }
    out
}

pub(in crate::monster) fn json_string_literal(value: &str) -> String {
    let mut out = String::with_capacity(value.len() + 2);
    out.push('"');
    for ch in value.chars() {
        match ch {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            ch if ch.is_control() => out.push_str(&format!("\\u{:04x}", ch as u32)),
            ch => out.push(ch),
        }
    }
    out.push('"');
    out
}

