    fn assert_close(actual: f64, expected: f64, tol: f64, label: &str) {
        let diff = (actual - expected).abs();
        assert!(
            diff <= tol,
            "{label}: |{actual} - {expected}| = {diff} > {tol}"
        );
    }

    #[test]
