#[test]
fn monster_builds_typed_gpu_buffer_abi_from_forge_ir() {
    let path = fresh_path("compute-gpu-buffer-abi");
    let monster = MonsterNode::new(
        Store::open(&path).unwrap(),
        MemoryGovernor::new(1024 * 1024),
    );
    let prepared = monster
        .prepare_forge_source(&forge_parallel_reduce_source(), std::iter::empty::<String>())
        .unwrap();

    assert_eq!(prepared.gpu_batch_plan.abi_hash.len(), 64);
    assert!(prepared.gpu_batch_plan.buffer_bindings.len() >= 5);
    assert_eq!(prepared.gpu_batch_plan.buffer_bindings[0].name, "monster_runtime_seeds");
    assert_eq!(prepared.gpu_batch_plan.buffer_bindings[0].binding, 0);
    assert_eq!(prepared.gpu_batch_plan.buffer_bindings[1].name, "monster_kernel_readback");
    assert_eq!(prepared.gpu_batch_plan.buffer_bindings[1].access, "read_write");

    let samples = prepared
        .gpu_batch_plan
        .buffer_bindings
        .iter()
        .find(|binding| binding.name == "samples")
        .unwrap();
    assert_eq!(samples.role, "input");
    assert_eq!(samples.access, "read");
    assert_eq!(samples.forge_type, "array<f64,8>");
    assert_eq!(samples.byte_width % samples.alignment_bytes, 0);
    assert_eq!(samples.init_policy, "sample_broadcast_first_case");
    assert_eq!(samples.init_hash.len(), 64);
    assert_eq!(samples.init_bytes.len() as u64, samples.byte_width);
    assert_eq!(
        f64::from_le_bytes(samples.init_bytes[0..8].try_into().unwrap()),
        1.0
    );
    assert_eq!(
        f64::from_le_bytes(samples.init_bytes[56..64].try_into().unwrap()),
        1.0
    );

    let bias = prepared
        .gpu_batch_plan
        .buffer_bindings
        .iter()
        .find(|binding| binding.name == "bias")
        .unwrap();
    assert_eq!(bias.role, "constant");
    assert_eq!(bias.init_policy, "constant_scalar_value");
    assert_eq!(f64::from_le_bytes(bias.init_bytes[0..8].try_into().unwrap()), 1.0);

    let total = prepared
        .gpu_batch_plan
        .buffer_bindings
        .iter()
        .find(|binding| binding.name == "total")
        .unwrap();
    assert_eq!(total.role, "output");
    assert_eq!(total.access, "read_write");
    assert_eq!(total.binding, 4);
    assert_eq!(total.init_policy, "zero_output");
    assert_eq!(prepared.route.plan.compute_ir_buffers.len(), 3);
    assert_eq!(prepared.route.plan.result_artifacts.len(), 1);
    assert_eq!(prepared.route.plan.result_artifacts[0].forge_type, "f64");
    assert_eq!(prepared.route.plan.result_artifacts[0].layout, "scalar_or_packed_value");
    assert_eq!(prepared.route.plan.result_artifacts[0].artifact_page_hash.len(), 64);
    assert_eq!(prepared.route.plan.numeric_policy.precision, "f64");
    assert_eq!(prepared.route.plan.numeric_policy.nan_inf_policy, "trap_and_deny_on_non_finite");
    assert_eq!(prepared.route.plan.numeric_policy.bounds_policy, "trap_on_declared_bounds_violation");
    assert_eq!(prepared.route.plan.numeric_policy.policy_hash.len(), 64);
    assert_eq!(prepared.route.plan.differential_test_plan.oracle_count, 1);
    assert_eq!(prepared.route.plan.differential_test_plan.tolerance_ppm, 10);
    assert_eq!(prepared.route.plan.differential_test_plan.plan_hash.len(), 64);
    assert_eq!(
        prepared.gpu_batch_plan.multi_adapter_schedule.merge_policy,
        "stable_offset_lane_readback_concat_then_hash"
    );
    assert_eq!(prepared.gpu_batch_plan.multi_adapter_schedule.schedule_hash.len(), 64);
    assert!(prepared
        .gpu_batch_plan
        .buffer_bindings
        .iter()
        .all(|binding| binding.buffer_hash.len() == 64));
    assert!(prepared
        .gpu_batch_plan
        .kernels
        .iter()
        .all(|kernel| kernel.shader_cache_key.len() == 64));

    let _ = std::fs::remove_dir_all(&path);
}

#[test]
fn monster_carries_forge_property_relations_into_the_compute_graph_plan() {
    let with_props = r#"
forge_module:
  module property_plan version 1
forge_imports:
  none
forge_constants:
  none
forge_functions:
  fn scaled(x: f64) -> f64 { return mul(x, 2.0) }
forge_program:
  emit y: f64 = scaled(x)
forge_inputs:
  param x: f64 unit none bounds [0.0, 10.0] nominal 1.0
forge_outputs:
  output y: f64 unit none handoff scalar
forge_constraints:
  assert finite(y)
forge_samples:
  case one { given x=1.0; expect y approx 2.0 tolerance 0.01 }
forge_properties:
  property finite_y: finite(y) tolerance 0.0
  property range_y: range(y, 0.0, 20.0) tolerance 0.001
  property monotone_y: monotone_increasing(y, x) tolerance 0.0001
forge_cost:
  max_steps=2000
  max_memory_mb=4
  precision=f64
artifact_handoff:
  proof_hash,output_hash
"#;
    let plan = crate::monster::compute_graph::MonsterComputeGraphPlan::from_forge_source(with_props).expect("plan builds");
    assert_eq!(plan.property_contract.len(), 3);
    let check = &plan.property_check_plan;
    assert_eq!(check.schema, "forge.monster.property_check_plan.v1");
    assert_eq!(check.relation_count, 3);
    assert_eq!(check.static_count, 2); // finite + range
    assert_eq!(check.runtime_count, 1); // monotonicity
    assert_eq!(check.plan_hash.len(), 64);
    assert!(check
        .relations
        .iter()
        .all(|relation| relation.relation_hash.len() == 64));
    let monotone = check
        .relations
        .iter()
        .find(|relation| relation.kind == "monotone_increasing")
        .expect("monotone relation present");
    assert_eq!(monotone.enforcement, "runtime_metamorphic");
    assert_eq!(monotone.target, "y");
    assert_eq!(monotone.params, vec!["x".to_string()]);
    let range = check
        .relations
        .iter()
        .find(|relation| relation.kind == "range")
        .expect("range relation present");
    assert_eq!(range.enforcement, "static_bounds");

    // Declaring properties must change the compute graph proof hash: invariants
    // are sealed into the plan, not silently dropped.
    let without_props = with_props
        .replace("forge_properties:\n", "")
        .replace("  property finite_y: finite(y) tolerance 0.0\n", "")
        .replace("  property range_y: range(y, 0.0, 20.0) tolerance 0.001\n", "")
        .replace("  property monotone_y: monotone_increasing(y, x) tolerance 0.0001\n", "");
    let bare = crate::monster::compute_graph::MonsterComputeGraphPlan::from_forge_source(&without_props).expect("bare plan builds");
    assert_eq!(bare.property_contract.len(), 0);
    assert_eq!(bare.property_check_plan.relation_count, 0);
    assert_ne!(plan.proof_hash, bare.proof_hash);
}

#[test]
fn monster_assigns_specialized_profiles_to_frontier_primitive_families() {
    let cases = [
        ("fft", "wgsl.signal_stockham_fft_pass.v1"),
        ("csr_matvec", "wgsl.sparse_csr_graphblas_spmv.v1"),
        ("bfs_step", "wgsl.graph_frontier_csr_traversal.v1"),
        ("svd_small", "wgsl.linalg_small_factorization.v1"),
        ("ode_step_rk4", "wgsl.solver_rk4_stencil.v1"),
        ("jvp", "wgsl.autodiff_dual_jvp_vjp.v1"),
        ("sha256_block", "wgsl.crypto_sha256_block.v1"),
        ("blake3_chunk", "wgsl.crypto_blake3_chunk.v1"),
        ("merkle_pair", "wgsl.crypto_blake3_merkle_pair.v1"),
        ("hmac_block", "wgsl.crypto_hmac_sha256_block.v1"),
        ("xor_stream", "wgsl.crypto_chacha20_xor_stream.v1"),
        ("random_oracle_probe", "wgsl.crypto_sha256_random_oracle.v1"),
    ];
    for (op, expected) in cases {
        let ops = vec![op.to_string()];
        assert_eq!(
            crate::monster::compute_graph::shader_profile_for_kernel("elementwise", &ops),
            expected,
            "primitive {op} should select a specialized Monster shader profile"
        );
        let wgsl = crate::monster::compute_graph::wgsl_for_kernel_plan("elementwise", &ops, 64);
        assert!(wgsl.contains("@compute"));
        assert!(wgsl.contains("@group(0) @binding(2)"));
    }
}

#[test]
fn monster_lowers_objective1_families_to_specialized_kernels() {
    let cases: [(&str, &str, &[&str]); 10] = [
        (
            "fft",
            "wgsl.signal_stockham_fft_pass.v1",
            &["fn stockham_butterfly", "let half = 1u << stage;", "cos(angle)"],
        ),
        (
            "convolution",
            "wgsl.signal_tiled_convolution.v1",
            &["var<workgroup> tile", "workgroupBarrier()", "while (k <= radius * 2u)"],
        ),
        (
            "csr_matvec",
            "wgsl.sparse_csr_graphblas_spmv.v1",
            &["fn graphblas_semiring_mul_add", "let row_start", "while (edge < row_end)"],
        ),
        (
            "bfs_step",
            "wgsl.graph_frontier_csr_traversal.v1",
            &["frontier_mask", "edge_count", "discovered"],
        ),
        (
            "svd_small",
            "wgsl.linalg_small_factorization.v1",
            &["fn jacobi_eigen_2x2", "let l00", "let sv0"],
        ),
        (
            "ode_step_rk4",
            "wgsl.solver_rk4_stencil.v1",
            &["fn rk4_step", "let laplacian", "let k4"],
        ),
        (
            "jvp",
            "wgsl.autodiff_dual_jvp_vjp.v1",
            &["fn dual_jvp", "fn dual_vjp", "let hessian_diag"],
        ),
        (
            "xor_stream",
            "wgsl.crypto_chacha20_xor_stream.v1",
            &["fn chacha_quarter_round", "while (round < 10u)", "let cipher = word ^ keystream"],
        ),
        (
            "random_oracle_probe",
            "wgsl.crypto_sha256_random_oracle.v1",
            &["fn oracle_k256", "w[15] = 320u", "while (i < 64u)"],
        ),
        (
            "hmac_block",
            "wgsl.crypto_hmac_sha256_block.v1",
            &["const HMAC_IPAD", "fn hmac_sha256_compress", "outer_digest_block[15] = 768u"],
        ),
    ];

    for (op, expected_profile, markers) in cases {
        let ops = vec![op.to_string()];
        let profile = crate::monster::compute_graph::shader_profile_for_kernel("elementwise", &ops);
        assert_eq!(profile, expected_profile, "{op} should use the specialized objective-1 profile");
        assert!(
            !profile.contains("probe") && !profile.contains("reference"),
            "{op} should no longer use a first-stratum probe/reference profile"
        );
        let wgsl = crate::monster::compute_graph::wgsl_for_kernel_plan("elementwise", &ops, 64);
        for marker in markers {
            assert!(wgsl.contains(marker), "{op} shader missing marker {marker}");
        }
    }
}

#[test]
fn monster_lowers_hmac_block_to_sha256_hmac_kernel() {
    let ops = vec!["hmac_block".to_string()];
    assert_eq!(
        crate::monster::compute_graph::shader_profile_for_kernel("elementwise", &ops),
        "wgsl.crypto_hmac_sha256_block.v1"
    );

    let wgsl = crate::monster::compute_graph::wgsl_for_kernel_plan("elementwise", &ops, 64);
    assert!(wgsl.contains("@compute @workgroup_size(64)"));
    assert!(wgsl.contains("@group(0) @binding(2) var<storage, read> in0: array<f32>;"));
    assert!(wgsl.contains("const HMAC_IPAD: u32 = 0x36363636u;"));
    assert!(wgsl.contains("const HMAC_OPAD: u32 = 0x5c5c5c5cu;"));
    assert!(wgsl.contains("fn hmac_sha256_compress"));
    assert!(wgsl.contains("inner_pad[i] = key_word ^ HMAC_IPAD;"));
    assert!(wgsl.contains("outer_pad[i] = key_word ^ HMAC_OPAD;"));
    assert!(wgsl.contains("inner_padding[15] = 1024u;"));
    assert!(wgsl.contains("outer_digest_block[15] = 768u;"));
    assert!(wgsl.contains("mac = hmac_sha256_compress(mac, outer_digest_block);"));
    assert!(wgsl.contains("atomicAdd(&out[3], mac[3] ^ mac[7]);"));
    assert!(
        !wgsl.contains("f01_from_u32(mix32"),
        "hmac_block must use a SHA-256 HMAC kernel, not the generic hash probe"
    );
}

#[test]
fn monster_lowers_merkle_pair_to_blake3_parent_kernel() {
    let ops = vec!["merkle_pair".to_string()];
    assert_eq!(
        crate::monster::compute_graph::shader_profile_for_kernel("elementwise", &ops),
        "wgsl.crypto_blake3_merkle_pair.v1"
    );

    let wgsl = crate::monster::compute_graph::wgsl_for_kernel_plan("elementwise", &ops, 64);
    assert!(wgsl.contains("@compute @workgroup_size(64)"));
    assert!(wgsl.contains("@group(0) @binding(2) var<storage, read> in0: array<f32>;"));
    assert!(wgsl.contains("const BLAKE3_PARENT: u32 = 0x04u;"));
    assert!(wgsl.contains("fn blake3_parent_g"));
    assert!(wgsl.contains("fn blake3_parent_round"));
    assert!(wgsl.contains("fn blake3_parent_permute"));
    assert!(wgsl.contains("let pair_base = (lane * 16u) % n;"));
    assert!(wgsl.contains("v[12] = 0u;"));
    assert!(wgsl.contains("v[13] = 0u;"));
    assert!(wgsl.contains("v[14] = 64u;"));
    assert!(wgsl.contains("v[15] = BLAKE3_PARENT;"));
    assert!(wgsl.contains("while (round < 7u)"));
    assert!(wgsl.contains("atomicAdd(&out[3], parent3 ^ parent7);"));
    assert!(
        !wgsl.contains("f01_from_u32(mix32"),
        "merkle_pair must use a BLAKE3 parent compression kernel, not the generic hash probe"
    );
}

