#[test]
fn monster_plans_sdf_handoff_as_native_tandem_artifact() {
    let path = fresh_path("compute-graph-sdf");
    let monster = MonsterNode::new(
        Store::open(&path).unwrap(),
        MemoryGovernor::new(1024 * 1024),
    );
    let source = forge_compute_source("sdf_compute", "sdf", 100_000, Some(8));
    let plan = monster.plan_forge_source(&source).unwrap();

    assert_eq!(plan.scale, MonsterComputeScale::Mini);
    assert_eq!(plan.backend_hint, MonsterBackendHint::NativeTandem);
    assert!(!plan.frame_blocking_allowed);
    assert_eq!(plan.outputs[0].handoff, "sdf");
    assert!(plan.outputs[0].native_ready);
    assert_eq!(plan.native_ready_outputs().len(), 1);

    let _ = std::fs::remove_dir_all(&path);
}

#[test]
fn monster_routes_dom_ram_graph_to_native_tandem_memoryreading() {
    let path = fresh_path("compute-graph-dom-ram");
    let monster = MonsterNode::new(
        Store::open(&path).unwrap(),
        MemoryGovernor::new(1024 * 1024),
    );
    let source = forge_dom_ram_graph_source();
    let route = monster.route_forge_source(&source).unwrap();

    assert_eq!(route.schema, "forge.monster.engine.route.v1");
    assert_eq!(route.lane, MonsterEngineLane::NativeTandemDomRam);
    assert_eq!(route.native_domain, MonsterNativeTandemDomain::DomRam);
    assert_eq!(route.blocking_policy, "never_block_browser_event_loop");
    assert_eq!(route.plan.backend_hint, MonsterBackendHint::NativeTandem);
    assert!(route.plan.outputs[0].native_ready);
    assert!(route
        .legacy_disposition
        .iter()
        .any(|item| item.family == "swarm/walkforward/nnue/seminaive/lua_table"
            && item.decision == "quarantine_or_extract"));

    let template = monster.universal_compute_template();
    assert_eq!(template.command, "/newcompute_");
    assert!(template.lanes.contains(&"native_tandem_dom_ram"));

    let prepared = monster
        .prepare_forge_source(&source, std::iter::empty::<String>())
        .unwrap();
    assert_eq!(prepared.native_tandem_artifacts.len(), 3);
    assert!(prepared
        .native_tandem_artifacts
        .iter()
        .all(|artifact| artifact.domain == "dom_ram"
            && artifact.artifact_hash.len() == 64
            && artifact.live_resume_cursor.len() == 64
            && artifact.live_slice_hash.len() == 64
            && artifact.live_section_owner == "webexplorer.dom_ram_cartography"
            && artifact.live_capture_policy != "not_live_browser_capture"
            && artifact.live_backpressure_policy != "not_applicable"
            && artifact.page_count > 0
            && !artifact.pages.is_empty()
            && &artifact.pages[0].bytes[0..4] == b"MDR4"));
    assert!(prepared
        .native_tandem_artifacts
        .iter()
        .any(|artifact| artifact.kind == "dom_graph_page"
            && artifact.layout == "live_cdp_domsnapshot_csr_graph_incremental_node_edge_u64_records"));
    assert!(prepared
        .native_tandem_artifacts
        .iter()
        .any(|artifact| artifact.kind == "ram_region_table"
            && artifact.layout == "live_columnar_ram_region_table_resumable_hash_offset_len_flags"));
    assert!(prepared
        .native_tandem_artifacts
        .iter()
        .any(|artifact| artifact.kind == "browser_event_loop_slice"
            && artifact.layout == "live_nonblocking_browser_event_loop_slice_backpressure_manifest"));

    let _ = std::fs::remove_dir_all(&path);
}

