#[test]
fn monster_executes_mass_compute_through_rust_rhi_when_gpu_is_available() {
    let path = fresh_path("compute-graph-gpu-execute");
    let monster = MonsterNode::new(
        Store::open(&path).unwrap(),
        MemoryGovernor::new(1024 * 1024),
    );
    let prepared = monster
        .prepare_forge_source(&forge_parallel_reduce_source(), std::iter::empty::<String>())
        .unwrap();

    assert!(prepared.gpu_batch_plan.required);
    let result = monster.execute_prepared_compute(&prepared);
    match result {
        Ok(execution) => {
            assert_eq!(execution.status, "gpu_executed_multi_adapter");
            assert_eq!(execution.backend, "rust_vulkan_rhi_multi_adapter");
            assert!(execution.detected_gpu_count >= 1);
            assert!(execution.used_gpu_count >= 1);
            assert_eq!(execution.lanes_executed, prepared.gpu_batch_plan.lanes);
            assert_eq!(execution.output_hash.len(), 64);
            assert_eq!(execution.proof_hash.len(), 64);
            assert_eq!(execution.differential_executions.len(), 1);
            let diff = &execution.differential_executions[0];
            assert_eq!(diff.candidate_backend, "rust_vulkan_rhi_multi_adapter");
            assert!(matches!(
                diff.status,
                "promoted_gpu_matches_cpu_production"
                    | "blocked_gpu_cpu_production_delta_exceeds_tolerance"
            ));
            assert_eq!(diff.proof_hash.len(), 64);
        }
        Err(crate::MonsterMassComputeError::GpuRequiredButUnavailable(error)) => {
            eprintln!("Monster GPU execute smoke skipped because no usable adapter was available: {error}");
        }
        Err(error) => panic!("unexpected Monster mass compute error: {error:?}"),
    }

    let _ = std::fs::remove_dir_all(&path);
}

