#[test]
fn monster_prepared_manifest_keeps_native_render_outputs_compact() {
    let path = fresh_path("compute-graph-prepared-native");
    let monster = MonsterNode::new(
        Store::open(&path).unwrap(),
        MemoryGovernor::new(1024 * 1024),
    );
    let source = forge_compute_source("prepared_sdf_compute", "sdf", 100_000, Some(16));

    let prepared = monster.prepare_forge_source(&source, std::iter::empty::<String>()).unwrap();

    assert_eq!(prepared.route.lane, MonsterEngineLane::NativeTandemRender);
    assert_eq!(prepared.route.native_domain, MonsterNativeTandemDomain::Render3d);
    assert_eq!(prepared.route.blocking_policy, "never_block_frame_loop");
    assert_eq!(prepared.native_ready_outputs.len(), 1);
    assert_eq!(prepared.native_ready_outputs[0].handoff, "sdf");
    assert_eq!(prepared.native_ready_output_hashes().len(), 1);
    assert_eq!(prepared.native_tandem_artifacts.len(), 5);
    let kinds = prepared
        .native_tandem_artifacts
        .iter()
        .map(|artifact| artifact.kind)
        .collect::<Vec<_>>();
    assert!(kinds.contains(&"sdf_brick"));
    assert!(kinds.contains(&"voxel_page"));
    assert!(kinds.contains(&"meshlet_page"));
    assert!(kinds.contains(&"surfel_radiance_cache"));
    assert!(kinds.contains(&"material_payload"));
    for artifact in &prepared.native_tandem_artifacts {
        assert_eq!(artifact.schema, "forge.monster.native_tandem.artifact.v1");
        assert_eq!(artifact.domain, "render_3d");
        assert_ne!(artifact.renderer_cache_class, "not_renderer_cache");
        assert!(matches!(
            artifact.renderer_cache_class,
            "sparse_vdb_leaf_cache"
                | "sparse_vdb_internal_residency_cache"
                | "gpu_driven_meshlet_culling_cache"
                | "multi_bounce_surfel_radiance_cache"
                | "material_variant_payload_cache"
        ));
        assert_eq!(artifact.renderer_cache_hash.len(), 64);
        assert_eq!(artifact.renderer_variant_hash.len(), 64);
        assert_eq!(artifact.renderer_promotion_hash.len(), 64);
        assert_ne!(artifact.renderer_residency_policy, "not_applicable");
        assert_ne!(artifact.renderer_culling_policy, "not_applicable");
        assert_eq!(artifact.artifact_hash.len(), 64);
        assert!(artifact.byte_len > 0);
        assert!(artifact.page_count > 0);
        assert!(!artifact.pages.is_empty());
        assert_eq!(&artifact.pages[0].bytes[0..4], b"MRC3");
        assert!(artifact.pages.iter().all(|page| page.page_hash.len() == 64));
        assert!(artifact
            .pages
            .iter()
            .flat_map(|page| page.bytes.iter())
            .any(|byte| *byte != 0));
    }
    assert!(prepared
        .native_tandem_artifacts
        .iter()
        .any(|artifact| artifact.layout == "nanovdb_like_sparse_vdb_leaf_8x8x8_f32_sdf_with_tile_mask"));
    assert!(prepared
        .native_tandem_artifacts
        .iter()
        .any(|artifact| artifact.layout == "gpu_driven_meshlet_page_64_vertices_cone_bounds_lod_error"));
    assert!(prepared
        .native_tandem_artifacts
        .iter()
        .any(|artifact| artifact.layout == "multi_bounce_surfel_radiance_cache_32_records_sh2"));
    assert!(prepared
        .native_tandem_artifacts
        .iter()
        .any(|artifact| artifact.layout == "pbr_material_variant_payload_f32_albedo_roughness_metallic_emissive"));
    assert!(prepared
        .cache_miss_work
        .iter()
        .all(|work| work.backend_hint == MonsterBackendHint::NativeTandem
            && !work.frame_blocking_allowed));

    let _ = std::fs::remove_dir_all(&path);
}

#[test]
fn monster_promotes_native_render_pages_to_production_renderer_caches() {
    let path = fresh_path("compute-render-production-caches");
    let monster = MonsterNode::new(
        Store::open(&path).unwrap(),
        MemoryGovernor::new(1024 * 1024),
    );
    let prepared = monster
        .prepare_forge_source(
            &forge_compute_source("render_cache_compute", "sdf", 100_000, Some(16)),
            std::iter::empty::<String>(),
        )
        .unwrap();

    let find = |kind: &str| {
        prepared
            .native_tandem_artifacts
            .iter()
            .find(|artifact| artifact.kind == kind)
            .unwrap()
    };
    let sdf = find("sdf_brick");
    assert_eq!(sdf.renderer_cache_class, "sparse_vdb_leaf_cache");
    assert!(sdf.layout.contains("sparse_vdb"));
    assert!(sdf.renderer_residency_policy.contains("sparse_vdb_pages"));
    assert!(sdf.renderer_culling_policy.contains("empty_tile_skip"));
    assert_eq!(&sdf.pages[0].bytes[0..4], b"MRC3");

    let meshlet = find("meshlet_page");
    assert_eq!(meshlet.renderer_cache_class, "gpu_driven_meshlet_culling_cache");
    assert!(meshlet.layout.contains("cone_bounds_lod_error"));
    assert!(meshlet.renderer_culling_policy.contains("frustum_occlusion_lod_error"));
    assert!(meshlet.byte_len >= 64 * 12 * 4);

    let radiance = find("surfel_radiance_cache");
    assert_eq!(radiance.renderer_cache_class, "multi_bounce_surfel_radiance_cache");
    assert!(radiance.layout.contains("multi_bounce"));
    assert!(radiance.renderer_residency_policy.contains("temporal_epoch"));
    assert!(radiance.byte_len >= 32 * 15 * 4);

    let material = find("material_payload");
    assert_eq!(material.renderer_cache_class, "material_variant_payload_cache");
    assert!(material.layout.contains("material_variant"));
    assert!(material.renderer_residency_policy.contains("shader_hash"));
    assert!(material.byte_len >= 4 * 12 * 4);

    let promotion_hashes = prepared
        .native_tandem_artifacts
        .iter()
        .map(|artifact| artifact.renderer_promotion_hash.as_str())
        .collect::<std::collections::BTreeSet<_>>();
    assert_eq!(promotion_hashes.len(), prepared.native_tandem_artifacts.len());
    assert_eq!(prepared.manifest_hash.len(), 64);

    let _ = std::fs::remove_dir_all(&path);
}

fn opaque_affine_program(rounds: usize) -> Program {
    let mut nodes = vec![Node::input(0)];
    let mut current = 0u16;
    for _ in 0..rounds {
        let eq = nodes.len() as u16;
        nodes.push(Node::eq(current, current));
        let zero = nodes.len() as u16;
        nodes.push(Node::const_i64(0));
        let selected = nodes.len() as u16;
        nodes.push(Node::select_i64(eq, current, zero));
        current = selected;
    }
    let two = nodes.len() as u16;
    nodes.push(Node::const_i64(2));
    let doubled = nodes.len() as u16;
    nodes.push(Node::mul(current, two));
    let five = nodes.len() as u16;
    nodes.push(Node::const_i64(5));
    let shifted = nodes.len() as u16;
    nodes.push(Node::add(doubled, five));
    nodes.push(Node::output(shifted, Ty::I64));
    Program::new(Target::Cpu, 1, 1, nodes.len() as u32, nodes).unwrap()
}

